[186] = {"Beherrschen der Tigerjagd", {"Ajeck Rouack von Nesingwarys Expedition möchte, dass Ihr 10 Schlingendorntiger tötet."}},
[187] = {"Beherrschen der Tigerjagd", {"Ajeck Rouack von Nesingwarys Expedition möchte, dass Ihr 10 alte Schlingendorntiger tötet."}},
[188] = {"Beherrschen der Tigerjagd", {"Ajeck Rouack von Nesingwarys Expedition möchte, dass Ihr Sin'Dall tötet und mit ihrer Tatze zurückkehrt."}},
