[209] = {"Hauer der Skullsplitter", {"Besorgt 18 Hauer der Skullsplitter und bringt sie zu Kebok."}},
[210] = {"Kochen mit Krazek", {"Bringt Krazeks Spezialtopf zu Krazek, dem Goblin."}},
[212] = {"Eine kalte Mahlzeit", {"Tötet einen Kaltaugenbasilisken, beschafft Euch einen gekühlten Basiliskenschenkel und bringt ihn Angus Stern im Blauen Eremiten.","","<Um diese Aufgabe erfolgreich abschließen zu können, dürft Ihr Euren Geist nicht freigeben.>"}},
