[216] = {"Hart auf hart", {"Schaltet 12 Rächer der Distelfelle und 12 Schamanen der Distelfelle aus. Man findet sie am häufigsten östlich vom Zoramstrand im Distelfelllager. Wenn das erledigt ist, kehrt zu Karang Amakkar in den Zoram'gar-Außenposten in Ashenvale zurück."}},
[217] = {"Verteidigung der Länder des Königs", {"Tötet den Anführer der Troggs, Grawmug, sowie seine beiden Wachen, Knirscher und Muskelprotz, und erstattet dann Captain Rugelfuss im südlichen Wachturm Bericht."}},
