[220] = {"Ruf des Wassers", {"Bringt die Phiole mit reinstem Wasser in das Brachland zu Islen Waterseer."}},
[221] = {"Worgs in den Wäldern", {"Tötet für Calor aus Dunkelhain 12 Dunkelläufer der Nachtheuler."}},
[222] = {"Worgs in den Wäldern", {"Tötet für Calor aus Dunkelhain einige Worgs, und zwar 8 Faulreißer der Nachtheuler und 8 besudelte Nachtheuler."}},
[223] = {"Worgs in den Wäldern", {"Bringt Calors Notiz zu Jonathan Carevin."}},
[224] = {"Verteidigung der Länder des Königs", {"Gebirgsjäger Cobbleflint vom südlichen Wachturm möchte, dass Ihr 10 Stonesplitter-Troggs und 10 Stonesplitter-Späher tötet."}},
[225] = {"Das verwitterte Grab", {"Sprecht in Dunkelhain mit Sirra Von'Indi."}},
[226] = {"Wölfe auf den Fersen", {"Tötet 12 verhungernde Terrorwölfe und 8 tollwütige Terrorwölfe und kehrt dann zu Lars in Svens Lager an der westlichen Grenze des Dämmerwalds zurück."}},
