[244] = {"Eindringende Gnolle", {"Erstattet Deputy Feldon Bericht."}},
[245] = {"Gefahr auf acht Beinen", {"Erledigt 15 Zwerggiftweberspinnen und meldet Euch dann wieder bei Behüter Dodds im Dämmerwald."}},
[246] = {"Einschätzung der Gefahr", {"Tötet 10 Bastarde der Rotkammgnolle und 6 Wilderer der Rotkammgnolle und meldet Euch anschließend wieder bei Deputy Feldon in Seenhain."}},
[247] = {"Die Jagd ist abgeschlossen", nil},
[248] = {"Weitere Beobachtungen", {"Steigt in den unversehrten Wachturm neben der Burg Steinwacht hinauf.","","Findet einen passenden Behälter für die Glyphe von Azora und legt diese dort ab."}},
[249] = {"Morganth", {"Besiegt Morganth.","","Bringt seinen Schattenanhänger zu Theocritus am Turm von Azora im Wald von Elwynn."}},
[250] = {"Eine dunkle Bedrohung", {"Untersucht den Bereich um die östliche Dammrampe und bringt Chefingenieur Hinderweir einen Hinweis, der Auskunft darüber geben könnte, was die Dunkeleisenzwerge vorhaben."}},
[251] = {"Übersetzung von Calvinius' Notiz", {"Bringt den Brief an Ello zu Sirra Von'Indi."}},
