[253] = {"Braut des Einbalsamierers", {"Findet Elizas Grab. Beschafft das Herz des Einbalsamierers, das sie in sich trägt, und kehrt zu Ello Ebonlocke zurück."}},
[254] = {"Graben in der Erde", nil},
[255] = {"Söldner", {"Magistrat Bluntnose aus Thelsamar hat Euch angeheuert, um 4 Oger der Mo'grosh, 4 Schläger der Mo'grosh und 4 Vollstrecker der Mo'grosh zu töten."}},
