[263] = {"Verteidigung der Länder des Königs", {"Gebirgsjäger Wallbang im südlichen Wachturm möchte, dass Ihr 10 Schamanen der Splittersteintroggs und 10 Knochenknacker der Splittersteintroggs tötet."}},
[264] = {"Bis dass der Tod uns scheidet", {"Legt Clarices Anhänger auf Yurivs Grab in Silberwald."}},
