[270] = {"Die verlorene Flotte", {"Geht zum Hafen von Menethil im Sumpfland und sprecht mit Glorin Steelbrow."}},
[271] = {"Vyrins Rache", {"Tötet Old Sooty und zeigt Daryl dem Jüngling in der Weitschreiter-Lodge dann Euer Werk."}},
[272] = {"Prüfung des Seelöwen", {"Sucht die Anhängerhälfte der Wasserbeweglichkeit und die Anhängerhälfte der Wasserausdauer. Sprecht mit den Einwohnern von Moonglade, um Hinweise darauf zu erhalten, wo sich diese Gegenstände befinden könnten.","","Formt den Anhänger des Seelöwen aus den beiden Anhängerhälften. Ihr müsst in der unmittelbaren Nähe des Schreins von Remulos sein, um dies zu tun.","","Bringt den zusammengefügten Anhänger zu Dendrite Starblaze nach Nighthaven in Moonglade."}},
[273] = {"Nachschub für die Ausgrabungsstätte", {"Sprecht mit Huldar."}},
[274] = {"Eine dunkle Bedrohung", {"Ashlan Stonesmirk möchte, dass Ihr zum Chefingenieur Hinderweir zurückkehrt und ihn von der neuen Entdeckung in Kenntnis setzt."}},
