[276] = {"Stapfende Pfoten", {"Tötet 15 Gnolle der Moosfelle sowie 10 Bastarde der Moosfelle und kehrt dann zu Rethiel dem Sumpfhüter im Sumpfland zurück."}},
[277] = {"Feuer-Tabu", {"Bringt Rethiel dem Sumpfhüter 9 kunstlose Feuersteine."}},
