[279] = {"Klauen aus der Tiefe", {"Tötet 12 Murlocs der Blaukiemen.","","Erschlagt Gobbler und nehmt Euch seinen Kopf.","","Bringt Gobblers Kopf zu Karl Boran in den Hafen von Menethil"}},
[280] = {"Eine dunkle Bedrohung", {"Chefingenieur Hinderweir will, dass Ihr zum Fuß des Dammes hinunterschwimmt, das Pulverfässchen ausfindig macht und die Entschärfungsmixtur hineinrührt, um eine Explosion zu verhindern."}},
[281] = {"Waren-Wiederbeschaffung", {"Durchsucht die Kisten und Fässer in den Murloclagern an der Küste."}},
[282] = {"Senirs Beobachtungen", {"Sprecht mit Gebirgsjäger Thalos."}},
[283] = {"Eine dunkle Bedrohung", {"Die Entschärfungsmixtur scheint gewirkt zu haben. Kehrt zu Chefingenieur Hinderweir zurück und berichtet ihm die guten Neuigkeiten."}},
[284] = {"Die Suche geht weiter", {"Sucht nach der Menethil-Statuette."}},
[285] = {"Suche in weiteren Hütten", {"Sucht weiter in den Hütten der Murlocs nach der Menethil-Statuette."}},
[286] = {"Rückgabe der Statuette", {"Bringt Karl Boran die Menethil-Statuette."}},
[287] = {"Höhle der Frostmane", {"Erforscht die Höhle der Frostmane und tötet 5 Kopfjäger der Frostmane für Senir Whitebeard in Kharanos."}},
