[289] = {"Die verfluchte Crew", {"Vernichtet 13 verfluchte Seeleute, 5 verfluchte Matrosen und den ersten Maat Snellig. Bringt Snelligs Schnupftabakdose zum ersten Maat Fitzsimmons im Hafen von Menethil."}},
[290] = {"Brechen des Fluchs", {"Besorgt den Geldkassettenschlüssel der INTREPID von Kapitän Halyndor.","","Verwendet den Schlüssel, um die Geldkassette der INTREPID zu öffnen."}},
[291] = {"Die Berichte", {"Überbringt Senator Barin Redstone in Ironforge Senirs Bericht."}},
[292] = {"Das Auge von Paleth", {"Bringt Glorin Steelbrow das verfluchte Auge von Paleth."}},
[293] = {"Die Reinigung des Auges", {"Bringt Erzbischof Benedictus das verfluchte Auge von Paleth. Ihr findet Benedictus in der Kathedrale des Lichts, in der Stadt Stormwind."}},
[294] = {"Ormers Rache", {"Ormer Ironbraid von der Whelgars Ausgrabungsstätte möchte, dass Ihr 10 scheckige Kreischer und 10 scheckige Raptoren tötet."}},
[295] = {"Ormers Rache", {"Ormer Ironbraid möchte, dass Ihr 10 scheckige Sensenklauen- und 10 scheckige Scharfzahnraptoren tötet und dann zu ihm zu Whelgars Ausgrabungsstätte zurückkommt."}},
[296] = {"Ormers Rache", {"Ormer Ironbraid von der Whelgars Ausgrabungsstätte möchte, dass Ihr Sarlatan tötet und mit einer seiner Krallen zu ihm zurückkehrt, sobald Ihr die Aufgabe erledigt habt."}},
