[298] = {"Bericht über den Fortschritt der Ausgrabungen", {"Bringt Ironbands Fortschrittsbericht zu Jern Hornhelm in Thelsamar."}},
[299] = {"Enthüllung der Vergangenheit", {"Ausgrabungsleiter Whelgar wünscht, dass Ihr die Ausgrabungsstätte nach den 4 fehlenden Tafel-Fragmenten durchkämmt, Ados, Modr, Golm und Neru."}},
[301] = {"Meldung in Ironforge", {"Bringt Ironbands Fortschrittsbericht zu Ausgrabungsleiter Stormpike."}},
[302] = {"Pulver für Ironband", {"Sprecht in Thelsamar mit Jern Hornhelm."}},
[303] = {"Der Dunkeleisenkrieg", {"Motley Garmason in Dun Modr möchte, dass Ihr 15 Dunkeleisenzwerge, 5 Tunnelgräber der Dunkeleisenzwerge, 5 Saboteure der Dunkeleisenzwerge und 5 Demolierer der Dunkeleisenzwerge tötet."}},
[304] = {"Eine grausige Aufgabe", {"Tötet Balgaras den Niederträchtigen und bringt Longbraid dem Grimmigen vor Dun Modr sein Ohr."}},
