[306] = {"Auf der Suche nach dem Ausgrabungstrupp", {"Kehrt mit Merrins Nachricht zu Tarrel Rockweaver zurück."}},
[307] = {"Schmutzige Pfoten", {"Geht zur Silberbachmine und sucht 4 Sätze Bergarbeiter-Ausstattung zusammen.","","Kehrt dann zu Gebirgsjäger Stormpike zurück."}},
[308] = {"Jarvens Ablenkung", nil},
[309] = {"Beschützen der Fracht", {"Stellt sicher, dass sowohl Miran als auch seine Warenlieferung sicher an der Ausgrabungsstätte ankommen und setzt dann Ausgrabungsleiter Ironband davon in Kenntnis."}},
[310] = {"Bittere Rivalen", {"Vertauscht im Keller der Brauerei Donnerbräu in Kharanos ein Fass Donnerbier mit einem Fass Gerstenbräu."}},
[311] = {"Rückkehr zu Marleth", {"Bringt Marleth Gerstenbräu in Brewnall das Fass mit Donnerbier."}},
