[319] = {"Ein Gefallen für etwas Immerschimmer", {"Tötet 6 Eisklauenbären, 8 alte Klippeneber sowie 8 Schneeleoparden und kehrt dann zu Rejold Gerstenbräu nach Brewnall zurück."}},
