[322] = {"Gesegnete Waffe", {"Bringt Grimand Elmore in Stormwind die Kiste mit Lichtschmiedeblöcken."}},
[323] = {"Bewährungsprobe", {"Vernichtet 15 Skeletträuber, 3 Skelettheiler sowie 3 Skelettwärter und kehrt danach zu Sven zurück."}},
[324] = {"Die verlorenen Blöcke", {"Sammelt 5 Lichtschmiedeblöcke und kehrt dann zu Glorin Steelbrow im Sumpfland zurück."}},
[325] = {"Bewaffnet und bereit", {"Bringt Morbents Bann zu Sven im Dämmerwald."}},
[328] = {"Der versteckte Schlüssel", {"Verwendet den kleinen Messingschlüssel, um Buchhalter Herods Geldkassette zu öffnen."}},
