[330] = {"Patrouillen-Pläne", {"Sprecht mit Corporal Sethman."}},
[331] = {"Meldung bei Doren", {"Sprecht mit Lieutenant Doren."}},
[332] = {"Weinladen-Werbung", {"Geht zum Weingut Gallina und gebt Suzetta Gallina den Wein-Gutschein, um eine kostenlose Flasche Wein zu erhalten."}},
[333] = {"Harlan braucht Nachschub", {"Geht zur Schneiderei und Anpasserei am Kanal und bringt Rema Schneider Harlan Bagleys Kleidungs-Auftrag."}},
[334] = {"Eine Lieferung für Thurman", {"Geht zum Konfektionsgeschäft Larson im Magierviertel von Stormwind und gebt Thurman Schneider sein Nähkästchen."}},
[335] = {"Ein nobles Bräu", {"Zardeth Blackclaw möchte, dass Ihr ihm eine Tilloaträne aus Dunkelhain und eine Bisamwurzel aus dem Sumpfland bringt."}},
[336] = {"Ein nobles Bräu", {"Bringt Lord Wishock in der Halle der Bittsteller das Blackclaw-Starkbier."}},
[337] = {"Ein altes Geschichtsbuch", {"Bringt das Buch: \"Die Geschichte von Stormwind\" in die Bibliothek von Stormwind zurück."}},
[338] = {"Die Grünen Hügel des Schlingendorntals", {"Sammelt die fehlenden Seiten des Manuskripts von \"Die Grünen Hügel des Schlingendorntals”. Wenn alle vier Kapitel vollständig sind, bringt sie zu Barnil zurück."}},
[339] = {"Kapitel I", {"Bringt Barnil Stonepot die Seiten 1, 4, 6 und 8 von Nesingwarys \"Die Grünen Hügel des Schlingendorntals”, um Kapitel I zu vervollständigen."}},
[340] = {"Kapitel II", {"Bringt Barnil Stonepot die Seiten 10, 11, 14 und 16 von Nesingwarys \"Die Grünen Hügel des Schlingendorntals\", um Kapitel II zu vervollständigen."}},
[341] = {"Kapitel III", {"Bringt Barnil Stonepot die Seiten 18, 20, 21 und 24 von Nesingwarys \"Die Grünen Hügel des Schlingendorntals”, um Kapitel III zu vervollständigen."}},
[342] = {"Kapitel IV", {"Bringt Barnil Stonepot die Seiten 25, 26 und 27 von Nesingwarys \"Die Grünen Hügel des Schlingendorntals\", um Kapitel IV zu vervollständigen."}},
[343] = {"Reden über Kraft", {"Geht in die königliche Bibliothek der Feste von Stormwind und sprecht mit Milton Sheaf. Er kann das Buch über Metallurgie für Euch finden, das Bruder Kristoff für seine Rede benötigt."}},
[344] = {"Bruder Paxton", {"Sprecht mit Bruder Paxton in der Abtei von Nordhain."}},
[345] = {"Tinten-Zutaten", {"Sprecht mit Großknecht Oslow in Seenhain und fragt ihn nach Rethbaneisenerz."}},
[346] = {"Rückkehr zu Kristoff", {"Kehrt zu Bruder Kristoff auf den Kathedralenplatz zurück. Gebt ihm das Buch: \"Belastbarkeit von Eisen\"."}},
[347] = {"Rethbanerz", {"Sammelt 5 Fuhren Rethbanerz und bringt sie Bruder Paxton in der Bibliothek von Nordhain."}},
[348] = {"Schlingendornfieber", {"Sucht Hexendoktor Unbagwa und lasst ihn Mokk den Wilden beschwören. Bringt das Herz von Mokk zu Fin Fizracket."}},
[349] = {"Schlingendornfieber", nil},
[350] = {"Auf einen alten Freund verlassen", {"Sprecht mit Elling Trias in Stormwind."}},
[351] = {"Findet OOX-17/TN!", {"Bringt das Notsignal zum Leitroboter von Oglethorpe."}},
[353] = {"Stormpikes Lieferung", {"Bringt das Päckchen für Stormpike zu Gebirgsjäger Stormpike am Loch Modan."}},
[354] = {"Todesfälle in der Familie", {"Bringt Coleman Farthing in Brill Gregors Überreste, Nissas Überreste und Thurmans Überreste."}},
[355] = {"Gespräch mit Sevren", {"Sprecht mit Magistrat Sevren in Brill."}},
[356] = {"Patrouille zur Rückendeckung", {"Tötet 8 blutende Schrecken und 8 wandernde Geister und meldet Euch dann wieder bei Linnea in ihrem Lager."}},
