[1952] = {"Der Zauberstab des Magiers", {"Sprecht nach ihrem Ritual mit Tabetha."}},
[1953] = {"Rückkehr in die Marschen", {"Sprecht mit Tabetha."}},
[1954] = {"Die Höllenkugel", {"Bringt eine Höllenkugel zu Tabetha in den Marschen von Dustwallow."}},
[1955] = {"Die Austreibung", {"Tötet den Dämon der Kugel und sprecht dann mit Tabetha."}},
[1956] = {"Macht in Uldaman", {"Beschafft Euch eine Obsidiankraftquelle und bringt sie in die Marschen von Dustwallow zu Tabetha."}},
[1959] = {"Meldung bei Anastasia", {"Sprecht mit Anastasia Hartwell."}},
[1960] = {"Untersuchungen im Alchimistenladen", {"Besorgt eine Inkantation der Manifestation und eine Truhe mit Verwahrungskästen von Anastasia Hartwell. Bringt 3 gefüllte Verwahrungskästen, die Truhe mit Verwahrungskästen sowie die Inkantation der Manifestation zu Anastasia in Undercity."}},
[1961] = {"Materialsammlung", {"Bringt 10 Leinentücher und 6 Manaedelsteine aus Dalaran zu Josef Gregorian."}},
[1962] = {"Roben des Zauberfeuers", nil},
[1963] = {"Die Shattered-Hand", {"Tötet Tazan und bringt seinen Ranzen zu Therzok in der Kluft der Schatten in Orgrimmar."}},
[1978] = {"Die Todespirscher", {"Bringt Androns Geschäftsbuch zu Varimathras in der Halle der dunklen Fürstin in Undercity."}},
[1998] = {"Fenwick Thatros", {"Tötet Fenwick Thatros und bringt seinen Kopf zu Mennet Carkad im Schurkenviertel von Undercity."}},
[1999] = {"Werkzeuge des Handwerks", {"Sucht den Statusbericht von Dalaran und bringt ihn zu Mennet Carkad im Schurkenviertel von Undercity."}},
[2038] = {"Bingles' verschwundene Werkzeuge", {"Sucht Bingles' Werkzeuge und bringt sie ihm zurück. Es sind:","","Bingles' Schraubenschlüssel, Bingles' Schraubendreher, Bingles' Hammer und Bingles' Sprengstofftube."}},
[2039] = {"Sucht Bingles", {"Sucht Bingles Blastenheimer am Loch Modan."}},
[2040] = {"Unterirdischer Angriff", {"Holt das Gnoam-Sprecklesprocket aus den Todesminen und bringt es Shoni der Schtillen in Stormwind."}},
[2041] = {"Sprecht mit Shoni", {"Sprecht mit Shoni der Schtillen in Stormwind."}},
[2078] = {"Gyromasts Rache", {"Sucht Gelkaks Ersten Maat, den Dreschonator 4100, und führt ihn zu Gelkak zurück."}},
[2098] = {"Gyromasts Rettung", {"Sucht die drei Stücke von Gelkaks Schlüssel und bringt sie Gelkak Gyromast."}},
[2118] = {"Verseuchtes Land", {"Fangt einen lebenden tollwütigen Distelbären und bringt ihn zu Tharnariun."}},
[2138] = {"Ausrottung der Infizierten", {"Befreit den Wald von 20 tollwütigen Distelbären und kehrt dann zu Tharnariun Treetender in Dunkelküste zurück."}},
[2139] = {"Tharnariuns Hoffnung", {"Sucht und tötet die Höhlenmutter."}},
[2158] = {"Ruhe und Entspannung", {"Sprecht im Gasthaus Zur Höhle des Löwen mit Gastwirt Farley."}},
[2159] = {"Dolanaar-Lieferung", {"Bringt die Dolanaar-Lieferung zu Gastwirt Keldamyr."}},
[2160] = {"Vorräte für Tannok", {"Bringt die Kiste mit Gasthausvorräten zu Tannok Frosthammer in Kharanos."}},
[2161] = {"Die Bürde eines Peons", {"Bringt Ukors Bürde zu Gastwirt Grosk in Klingenhügel."}},
[2178] = {"Schreitereintopf", {"Bringt 5 Stücke Schreiterfleisch zu Alanndarian Nightsonng in Auberdine."}},
[2198] = {"Die zerrissene Halskette", {"Sucht nach dem Erschaffer der zerrissenen Halskette, um etwas über ihren möglichen Wert zu erfahren."}},
[2199] = {"Lehren haben ihren Preis", {"Bringt fünf Silberbarren zu Talvash del Kissel in Ironforge."}},
[2200] = {"Rückkehr nach Uldaman", {"Sucht in Uldaman nach Hinweisen auf den momentanen Zustand von Talvashs Halskette. Der getötete Paladin, den Talvash erwähnte, hatte die Kette zuletzt."}},
[2201] = {"Suche nach den Edelsteinen", {"Findet den Rubin, den Saphir und den Topas, die in ganz Uldaman verstreut sind. Wenn Ihr sie habt, wendet Euch aus der Ferne an Talvash del Kissel, indem Ihr die Wahrsagephiole nutzt, die er Euch zuvor gegeben hat.","","Aus dem Tagebuch, wisst Ihr...","* Der Rubin wurde in einer Bastion der Zwerge der Schattenschmiede versteckt.","* Der Topas steckt in einer Urne in einem der Trogg-Gebiete, in der Nähe einiger Zwerge der Allianz.","","* Der Saphir wurde von Grimlok, dem Anführer der Troggs, mitgenommen."}},
[2202] = {"Reagenzsuche in Uldaman", {"Bringt 12 magenta Funguskappen nach Kargath zu Jarkal Mossmeld."}},
[2203] = {"Reagenzien-Suche im Ödland II", {"Benutzt die leeren thaumaturgischen Gefäße bei versengten Wächtergroßdrachen im Ödland. Wenn Ihr sie gefüllt habt, bringt sie zu Jarkal Mossmeld in Kargath."}},
[2204] = {"Restaurierung der Halskette", {"Besorgt Euch eine Kraftquelle vom mächtigsten Konstrukt, das Ihr in Uldaman finden könnt, und liefert sie bei Talvash del Kissel in Ironforge ab."}},
[2205] = {"Aufsuchen des SI: 7", {"Liefert Keryn Sylvius' Päckchen an Meister Mathias Shaw in der Kaserne von Stormwind."}},
[2206] = {"Schneller Eingriff", {"Sucht den Dockmeister der Defias und beschafft den Lieferzeitplan für Meister Mathias Shaw."}},
[2218] = {"Straße der Rettung", {"Sprecht mit Hulfdan Blackbeard in Ironforge."}},
[2238] = {"Einfache List", {"Sucht Onin MacHammar bei Gnomeregan."}},
[2239] = {"Onins Bericht", {"Bringt Onins Bericht zu Hulfdan in Ironforge."}},
[2240] = {"Die geheime Kammer", {"Lest Baelogs Tagebuch, erforscht die geheime Kammer und erstattet dann Ausgrabungsleiter Stormpike Bericht."}},
[2241] = {"Der Apfel fällt", {"Bringt Jannoks Rose zu Syurna in Darnassus."}},
[2242] = {"Das Schicksal ruft", {"Sucht Sethir den Uralten und bringt alle Hinweise, die Ihr finden könnt, zu Syurna."}},
[2258] = {"Reagenzien-Suche im Ödland", {"Bringt Jarkal Mossmeld in Kargath im Ödland 5 Bussard-Mägen, 10 Klippenkojoten-Fangzähne und 5 Felselementarsplitter."}},
[2259] = {"Erion Shadewhisper", {"Kontaktiert Erion Shadewhisper in Darnassus."}},
[2260] = {"Erions Befehl", {"Reist zur Stadt Stormwind und meldet Euch bei Renzik \"Das Messer\"."}},
[2278] = {"Die Platinscheiben", {"Sprecht mit dem Steinbehüter und findet heraus, welche uralten Lehren er aufbewahrt. Sobald Ihr alles erfahren habt, was er weiß, aktiviert die Scheiben von Norgannon."}},
[2279] = {"Die Platinscheiben", {"Bringt die Miniaturausgabe der Scheiben von Norgannon zur Forscherliga nach Ironforge."}},
[2280] = {"Die Platinscheiben", {"Bringt die Miniaturausgabe der Scheiben von Norgannon zu einem der Weisen von Thunder Bluff."}},
[2281] = {"Rendezvous im Rotkammgebirge", {"Geht nach Seenhain im Rotkammgebirge und sprecht mit Lucius."}},
[2282] = {"Althers Mühle", {"Öffnet Lucius' Schließkassette, nehmt die Marke der Diebeskunst heraus und bringt sie zu Lucius nach Seenhain."}},
[2283] = {"Wiederbeschaffung der Halskette", {"Sucht in der Grabungsstätte von Uldaman nach einer wertvollen Halskette und bringt sie nach Orgrimmar zu Dran Droffers. Die Halskette ist vielleicht beschädigt."}},
[2284] = {"Wiederbeschaffung der Halskette, Teil 2", {"Sucht in den Tiefen von Uldaman nach einem Hinweis auf den Verbleib der Edelsteine."}},
[2298] = {"Königliche Erpressung", {"Reist nach Stormwind und sucht Renzik \"Das Messer\" auf."}},
[2299] = {"Auf Hulfdan!", {"Reist nach Ironforge und sprecht mit Hulfdan Blackbeard."}},
[2300] = {"Der SI:7", {"Reist nach Stormwind und sucht Renzik \"Das Messer\" auf."}},
[2318] = {"Übersetzung des Tagebuchs", {"Sucht jemanden, der das Tagebuch des Paladins übersetzen kann. Der nächstgelegene Ort, wo Ihr so jemanden finden könntet, ist Kargath im Ödland."}},
[2338] = {"Übersetzung des Tagebuchs", {"Leiht Jarkal die Halskette. Im Gegenzug wird er das Tagebuch für Euch übersetzen."}},
[2339] = {"Findet die Edelsteine und die Kraftquelle", {"Beschafft in Uldaman alle drei Edelsteine sowie eine Kraftquelle für die Halskette und bringt sie anschließend zu Jarkal Mossmeld nach Kargath. Jarkal glaubt, dass sich eine Kraftquelle vielleicht im stärksten Konstrukt in Uldaman findet.","","Aus dem Tagebuch, wisst Ihr...","* Der Rubin wurde in einer Bastion der Zwerge der Schattenschmiede versteckt.","* Der Topas steckt in einer Urne in einem der Trogg-Gebiete, in der Nähe einiger Zwerge der Allianz.","* Der Saphir wurde von Grimlok, dem Anführer der Troggs, mitgenommen."}},
[2340] = {"Ablieferung der Edelsteine", {"Liefert die Halskette und die geborgenen Edelsteine bei Dran Droffers in Orgrimmar ab."}},
[2341] = {"Wiederbeschaffung der Halskette, Teil 3", {"Besucht Jarkal Mossmeld in Kargath, um festzustellen, ob er Erfolg gehabt hat."}},
[2342] = {"Wiederbeschaffte Schätze", {"Holt Patrick Garretts Familienschatz aus der Truhe der Familie in der südlichen Bankenhalle von Uldaman und bringt diesen zu ihm nach Undercity."}},
[2359] = {"Klavens Turm", {"Stehlt den Turmschlüssel der Defias, brecht in den Turm der Defias ein und stellt fest, was sich in der Dämmerwaldtruhe befindet. Bringt Mathias Shaw in Stormwind dann alle Informationen über das, was Ihr herausgefunden habt. Lest Kearnens Tagebuch, um neue Erkenntnisse über den Turm zu erlangen."}},
[2360] = {"Mathias und die Defias", {"Reist nach Westfall und sucht Agentin Kearnen. Sie wird Euch Bericht erstatten."}},
[2361] = {"Restaurierung der Halskette", nil},
[2378] = {"Suche nach der Shattered-Hand", {"Reist nach Orgrimmar und sprecht an der Kluft der Schatten mit Shenthul."}},
[2379] = {"Zando'zan", {"Sprecht an der Kluft der Schatten mit Zando'zan."}},
[2380] = {"Nach Orgrimmar!", {"Sprecht an der Kluft der Schatten in Orgrimmar mit Shenthul."}},
[2381] = {"Das Ausplündern der Plünderer", {"Bringt den Schatz der Südmeerfreibeuter zu Wrenix dem Jämmerlichen in Ratchet. Vergesst nicht, einen R.C.V.K. und Diebeswerkzeug von Wrennixs Elektrodingsda-Apparat zu bringen. Ihr werdet diese Dinge brauchen, um Eure Mission zu beenden.","","Wenn Ihr von ungewöhnlich feindlichen Papageien angegriffen werdet, benutzt Euren R.C.V.K.!"}},
[2382] = {"Wrenix aus Ratchet", {"Reist nach Ratchet und sprecht mit Wrenix dem Jämmerlichen."}},
[2383] = {"Einfaches Pergament", {"Lest das einfache Pergament und sprecht mit Frang im Tal der Prüfungen."}},
[2398] = {"Die verschollenen Zwerge", {"Sucht in Uldaman nach Baelog."}},
[2399] = {"Die sprießenden Wedel", nil},
[2418] = {"Kraftsteine", {"Bringt Rigglefuzz im Ödland 8 Kraftsteine aus Dentrium und 8 Kraftsteine aus An'Alleum."}},
[2438] = {"Der smaragdgrüne Traumfänger", {"Bringt den smaragdgrünen Traumfänger zu Tallonkai Swiftroot in Dolanaar."}},
[2439] = {"Die Platinscheiben", {"Bringt Euren Belohnungsgutschein zu Dinita Stonemantle im Gewölbe von Ironforge."}},
[2440] = {"Die Platinscheiben", {"Bringt den Belohnungsgutschein zu Bena Winterhoof nach Thunder Bluff."}},
[2458] = {"Undercover", {"Reist zum Turm der Venture Company nördlich des Schlickermoores und kontaktiert dort den Agenten der Shattered-Hand, Zuchtmeister Fizzule.","","Sobald der Turm in Sichtweite ist, verwendet die Leuchtfeuerwaffe, um Zuchtmeister Fizzule Eure Ankunft anzuzeigen. Feuert ZWEI Leuchtfeuergeschosse ab, nähert Euch dann Zuchtmeister Fizzule und zeigt den Gruß der Shattered-Hand.","","Es ist wichtig, dass Ihr diese Aktionen in der richtigen Reihenfolge durchführt, da Fizzule jede Person, die er nicht erkennt, angreift und eliminiert."}},
[2459] = {"Ferocitas der Traumfresser", {"Tallonkai Swiftroot aus Dolanaar möchte, dass Ihr 7 Mystiker der Knarzklauen tötet und das verlorene Juwel findet."}},
[2460] = {"Der Shattered-Gruß", {"Führt Shenthul gegenüber den Shattered-Gruß aus."}},
[2478] = {"Mission: möglich, aber nicht sehr wahrscheinlich", {"Stehlt Silixiz' Turmschlüssel von Großknecht Silixiz. Tötet dann 2 mutierte Drohnen der Venture Co., 2 Patrouillen der Venture Co. und 2 Ausgucker der Venture Co.","","Eliminiert den obersten Großknecht Gallywix und nehmt seinen Kopf. Knackt dann das Schloss von Gallywix' Schließkassette und stehlt den Vorrat an Zanzils veränderter Mixtur. Bringt den Vorrat und Gallywix' Kopf zu Shentul nach Orgrimmar; er wird Euch weitere Anweisungen geben."}},
[2479] = {"Hinotts Hilfe", {"Reist nach Tarrens Mühle im Vorgebirge von Hillsbrad und liefert die Probe von Zanzils Mixtur bei Serge Hinott ab.","","Um nach Tarrens Mühle zu kommen, müsst Ihr den Zeppelin nach Undercity nehmen und dann auf der Straße nach Süden durch den Silberwald in Richtung Hillsbrad reisen. Folgt den Schildern!"}},
[2480] = {"Hinotts Hilfe", {"Wartet auf Serge Hinott, um das Heilmittel fertig zu stellen."}},
[2498] = {"Rückkehr zu Denalan", {"Rellian Greenspyre möchte, dass Ihr am Al'Amethsee mit Denalan sprecht."}},
[2499] = {"Grimmeiche", {"Denalan vom Al'Amethsee möchte, dass Ihr den riesengroßen Tumor von Grimmeiche einsammelt."}},
[2500] = {"Reagenzien-Suche im Ödland", {"Beschafft die Reagenzien, die Ghak Healtouch aus dem Ödland braucht, und bringt sie ihm nach Thelsamar."}},
[2501] = {"Reagenzien-Suche im Ödland II", {"Benutzt die leeren thaumaturgischen Gefäße bei versengten Wächtergroßdrachen im Ödland. Wenn Ihr sie gefüllt habt, bringt sie zu Ghak Healtouch in Thelsamar."}},
[2518] = {"Tränen des Mondes", {"Priesterin A'moora vom Tempel des Mondes in Darnassus möchte, dass Ihr ihr Lady Sathrahs silbrige Spinndrüsen bringt."}},
[2519] = {"Der Tempel des Mondes", {"Schwester Aquinne möchte, dass Ihr im Tempel des Mondes mit Priesterin A'moora sprecht."}},
[2520] = {"Sathrahs Opferung", {"Priesterin A'moora möchte, dass Ihr Lady Sathrahs silbrige Spinndrüsen am Brunnen innerhalb des Tempels ablegt und dann zu ihr zurückkehrt."}},
[2541] = {"Der schlafende Druide", {"Bringt einen Voodooglücksbringer des Schamanen zu Oben Zornklaue in den Grabhügel von Ban'ethil."}},
[2561] = {"Druide der Klaue", {"Oben Zornklaue möchte, dass Ihr seinen seelenlosen Körper tötet und dann den Voodooglücksbringer anwendet."}},
[2581] = {"Kicherfangunterkiefer", {"Bringt Blutmagier Drazial 3 Kicherfangunterkiefer, 2 feuerverbrannte Eberlungen und 1 Skorpokzange."}},
[2583] = {"Lebenskraft des Ebers", {"Bringt Blutmagier Drazial 3 feuerverbrannte Eberlungen, 2 Skorpokzangen und 1 Basiliskengehirn."}},
[2585] = {"Der Entscheidungsschlag", {"Bringt Blutmagier Drazial 3 Skorpokzangen, 2 Geiermuskelmägen und 1 feuerverbrannte Eberlunge."}},
[2601] = {"Der Biss des Basilisken", {"Bringt Blutmagierin Lynnore 10 Basiliskengehirne und 2 Geiermuskelmägen."}},
[2603] = {"Lebensenergie des Geiers", {"Bringt Blutmagierin Lynnore 10 Geiermuskelmägen und 2 Kicherfangunterkiefer."}},
[2605] = {"Der durstige Goblin", {"Beschafft Euch eine volle Taudrüse und bringt sie nach Gadgetzan zu Marin Noggenfogger."}},
[2606] = {"Dem guten Geschmacke", {"Marin Noggenfogger möchte, dass Ihr in Gadgetzan mit Sprinkle sprecht."}},
[2607] = {"Die Berührung von Zanzil", {"Sprecht im Keller der Kaserne mit Doc Mixilpixil."}},
[2608] = {"Die Berührung von Zanzil", {"Ihr solltet Euch /hinlegen, damit Doc Mixilpixil Euch untersuchen kann. Denn wie soll er ein Heilmittel finden, wenn er die Ursache nicht finden kann?"}},
[2609] = {"Die Berührung von Zanzil", {"Bringt Doc Mixilpixil 1 Bündel einfache Wildblumen, 1 verbleite Phiole, 1 Bronzeröhre und 1 Rolle blassgelben Seidenfaden. So eine 'Itis' heilt sich nicht von selbst, junger Herr."}},
[2621] = {"Der Entehrte", {"Sprecht in Stonard mit Zentralen-Kommandant Ruag."}},
[2622] = {"Die fehlenden Befehle", {"Sprecht mit Bengor."}},
[2623] = {"Der Sumpfredner", {"Beschafft die Befehle des Kriegshäuptlings wieder und gebt sie dem gefallenen Helden der Horde zurück."}},
[2641] = {"Sprinkles Geheimzutat", {"Sprinkle in Gadgetzan möchte, dass Ihr einen violetten Tragan sucht und ihr bringt."}},
[2661] = {"Lieferung für Marin", {"Sprinkle möchte, dass Ihr das violette Pulver nach Gadgetzan zu Marin Noggenfogger bringt."}},
[2662] = {"Noggenfogger-Elixier", {"Marin Noggenfogger möchte, dass Ihr ihn nochmals ansprecht, wenn er sein Elixier fertig gestellt hat."}},
[2681] = {"Die Steine, die uns binden", {"Befreit 9 Diener von Razelikh, 3 Diener von Sevine, 3 Diener von Allistarj und 3 Diener von Grol. Kehrt zum gefallenen Helden zurück, sobald Ihr die Aufgabe erfüllt habt. Ihr müsst nahe bei den Steinen bleiben, sonst habt Ihr keinen Erfolg."}},
[2741] = {"Der Super-Ei-O-Mat", nil},
[2742] = {"Rin'ji steckt in der Falle!", {"Eskortiert Rin'ji aus der Jagdhütte Quel'Danil heraus und findet dann das, was er bei den Aussichtsklippen im Osten versteckt hat."}},
[2745] = {"Eindringen ins Schloss", {"Sprecht in Schloss Stormwind mit Tyrion."}},
[2746] = {"Nicht unwichtige Gegenstände", {"Bringt 3 Stück Seidenstoff und 2 frische Äpfel von Clara nach Stormwind zu Tyrion."}},
[2747] = {"Ein außergewöhnliches Ei", nil},
[2748] = {"Ein gutes Ei", nil},
[2749] = {"Ein gewöhnliches Ei", nil},
[2750] = {"Ein schlechtes Ei", nil},
[2751] = {"Barbarische Waffenschmiedekunst", {"Bringt 2 gemusterte bronzene Armschienen, 2 bronzene Großschwerter und 2 scharfe Klauen zu Orokk Omosh in Orgrimmar."}},
[2752] = {"Über Eisenschulterstücke", {"Bringt 4 bronzene Streitäxte und 4 bronzene Kriegshämmer zu Orokk Omosh in Orgrimmar."}},
[2753] = {"In den Boden getrampelt", {"Bringt 4 grüne Eisenhelme, 4 grüne Eisenarmschienen und 2 grüne Eisengamaschen zu Orokk Omosh in Orgrimmar."}},
[2754] = {"Hörner der Raserei", {"Bringt 2 robuste Eisenschlägel, 2 bronzene Stiefel mit Versilberung und 2 bronzene Stulpen mit Versilberung zu Orokk Omosh in Orgrimmar."}},
[2755] = {"Freude der Omoshs", {"Seht zu und lernt den Freudentanz der Omoshs."}},
[2756] = {"Die alten Traditionen", {"Bringt 4 Stahlbrustplatten und 4 Stahlplattenhelme zu Aturk dem Amboss in Orgrimmar."}},
[2757] = {"Auf nach Booty Bay!", {"Sprecht mit McGavan in Booty Bay."}},
[2758] = {"Die Herkunft der Schmiedekunst", nil},
[2760] = {"Der Mithrilorden", {"Sprecht mit Galvan dem Alten im Schlingendorntal."}},
[2761] = {"Hier verhütten, da verhütten", {"Bringt Galvan dem Alten im Schlingendorntal 40 Mithrilbarren und 40 Eisenbarren."}},
[2762] = {"Der große silberne Betrüger", {"Bringt Galvan dem Alten im Schlingendorntal 40 Mithrilbarren und 5 Echtsilberbarren."}},
[2763] = {"Die Kunst der Magieerfüllung", {"Bringt Galvan dem Alten im Schlingendorntal 40 Mithrilbarren und 4 Citrine."}},
[2764] = {"Galvans bester Schüler", {"Sprecht in Gadgetzan mit Trenton Lighthammer."}},
[2765] = {"Schmiedkunstexperte!", {"Fordert Eure Belohnung von Galvan dem Alten ein!"}},
[2766] = {"Findet OOX-22/FE!", {"Bringt das Notrufsignal zu Oglethorpes Leitroboter in einer Höhle in der Nähe des Wildschrammtals."}},
[2767] = {"Die Rettung von OOX-22/FE", {"Eskortiert OOX-22/FE zum Dock an der Vergessenen Küste und meldet Euch dann bei Oglethorpe Obnoticus in Booty Bay."}},
[2768] = {"Wünschel-mato-Rute", {"Bringt die Wünschel-mato-Rute nach Gadgetzan zu Chefingenieur Bilgewhizzle."}},
[2769] = {"Die Brüder Brassbolt", {"Sprecht mit Wizzle Brassbolts in der schimmernden Ebene."}},
[2770] = {"Gahz'rilla", {"Bringt Wizzle Brassbolts in der schimmernden Ebene Gahz'rillas energiegeladene Schuppe."}},
[2771] = {"Ein schlauer Kopf auf den Schultern", {"Bringt Trenton Lighthammer 2 Mithrilhelmkappen und 1 verschnörkelte Mithrilschulter."}},
[2772] = {"Die Welt zu Euren Füßen", {"Bringt Trenton Lighthammer 2 schwere Mithrilstiefel und 1 verschnörkelte Mithrilhose."}},
[2773] = {"Mithril-Kid", {"Bringt Trenton Lighthammer 2 schwere Mithrilbrustplatten und 1 verschnörkelten Mithrilhandschuh."}},
[2781] = {"GESUCHT: Kalif Skorpidstich", {"Bringt Chefingenieur Bilgewhizzle in Gadgetzan den Kopf von Kalif Skorpidstich."}},
[2782] = {"Rin'jis Geheimnis", {"Oran Snakewrithe, eine bekannte Gelehrte auf dem Gebiet der Witherbarktrolle, könnte die Tafel vielleicht übersetzen. Normalerweise hält sie sich im Magierviertel von Undercity auf."}},
[2783] = {"Kleinliches Gezänk", {"Sprecht mit dem gefallenen Helden der Horde im Grenzgebiet zwischen den verwüsteten Landen und dem Sumpf."}},
[2784] = {"In Ungnade fallen", {"Lauscht der Geschichte des gefallenen Helden der Horde."}},
[2801] = {"Eine Geschichte voller Leid", {"Lauscht der Geschichte des gefallenen Helden der Horde."}},
[2821] = {"Das Zeichen der Qualität", {"Bringt Pratt McGrubben in der Festung Feathermoon 10 dicke Yetibälge."}},
[2822] = {"Das Zeichen der Qualität", {"Bringt Jangdor Swiftstrider im Camp Mojache 10 dicke Yetibälge."}},
[2841] = {"Maschinenkriege", {"Besorgt die Maschinenblaupausen und Thermapluggs Safekombination aus Gnomeregan und bringt sie zu Nogg nach Orgrimmar."}},
[2842] = {"Chefingenieur Scooty", {"Sprecht mit Scooty in Booty Bay."}},
[2843] = {"Gnomer-weeeeg!", {"Wartet, bis Scooty den Goblin-Transponder kalibriert hat."}},
[2844] = {"Der Riesenwächter", {"Findet das verlorene Nachtelfen-Mädchen."}},
[2845] = {"Streunende Shay", {"Nehmt Shays Glocke aus der Truhe.","","Begleitet Shay Leafrunner zu Felsbeißers Lager."}},
[2846] = {"Tiara der Tiefen", {"Bringt die Tiara der Tiefen zu Tabetha in den Marschen von Dustwallow."}},
[2847] = {"Wildlederrüstung", {"Bringt Pratt McGrubben in der Festung Feathermoon 10 Stücke dickes Leder."}},
[2848] = {"Wildlederschultern", {"Bringt Pratt McGrubben in der Festung Feathermoon 6 dicke Rüstungssets und eine Wildranke."}},
[2849] = {"Wildlederweste", {"Bringt Pratt McGrubben in der Festung Feathermoon 2 Schildkrötenschuppenbrustplatten, 2 Paar Schildkrötenschuppenhandschuhe und eine Wildranke."}},
