[3373] = {"Die Essenz des Eranikus", {"Legt die Essenz von Eranikus in den Essenzborn, der sich in dem Versunkenen Tempel in seinem Unterschlupf befindet."}},
[3374] = {"Die Essenz des Eranikus", {"Bringt den Schwurstein von Yseras Drachenschwarm sowie die gekettete Essenz von Eranikus zu Itharius in die Sümpfe des Elends. Dort werdet Ihr Eure Entscheidung treffen, ob Ihr Yseras Drachenschwarm helfen wollt oder nicht."}},
[3376] = {"Tötet Spitzhauer!", {"Bringt den Kopf von Häuptling Spitzhauer Dornenmantel zu Kriegerheld Windfeather nach Red Cloud Mesa."}},
[3377] = {"Gebet an Elune", {"Hört Zamaels Geschichte."}},
[3378] = {"Gebet an Elune", {"Findet das Gebet an Elune und bringt es zu Astarii Starseeker in Darnassus."}},
[3380] = {"Der versunkene Tempel", {"Sucht Marvon Rivetseeker in Tanaris."}},
