[3443] = {"Das Schmieden des Schafts", {"Bringt 8 mit Thorium beschichtete Dolche zu Velarok Windblade."}},
[3444] = {"Der runde Stein", {"Holt den runden Stein aus Marvon Rivetseekers Werkstatt in Ratchet."}},
[3445] = {"Der versunkene Tempel", {"Sucht Marvon Rivetseeker in Tanaris."}},
[3446] = {"In die Tiefen", {"Sucht den Altar von Hakkar im Versunkenen Tempel in den Sümpfen des Elends."}},
