[3449] = {"Arkane Runen", {"Verwendet das Zeichenset, um Abpausbilder von der Rune von Beth'Amara, der Rune von Jin'yael, der Rune von Markri und der Rune von Sael'hai herzustellen, bevor Ihr Euch zu der kleinen Insel vor der südlichen Halbinsel von Azshara aufmacht und dem Piloten Xiggs Fuselighter signalisiert, dass er sie abholen kann."}},
[3450] = {"Eine einfache Ladung", {"Sprecht mit Xiggs Fuselighter in Ironforge."}},
[3451] = {"Signal zum Abholen", {"Sprecht mit Xiggs Fuselighter in Ironforge und erhaltet von ihm eine Standardausrüstung-Leuchtfeuerwaffe."}},
[3452] = {"Die Ummantelung der Flamme", {"Bringt ein Symbol von Ragnaros zu Velarok Windblade."}},
[3453] = {"Die Fackel der Vergeltung", {"Wartet bis Velarok Windblade die Fackel der Vergeltung vollendet hat."}},
[3454] = {"Die Fackel der Vergeltung", {"Nehmt die Fackel der Vergeltung."}},
