[3463] = {"Setzt sie in Brand!", {"Steckt die Wachpostentürme im Norden, Süden, Osten und Westen in Brand, indem Ihr die Fackel der Vergeltung innerhalb der einzelnen Gebäude benutzt."}},
[3481] = {"Plunder...", {"Öffnet die Truhe."}},
