[3505] = {"Verraten", {"Tötet 6 Blutelfenwiederbeschaffer und 6 Blutelfenfeldmesser, bevor Ihr Euch aufmacht, Rimtoris Quelle der Macht zu finden."}},
[3512] = {"Mit Eranikus' eigenen Worten", {"Reist in den östlichen Teil von Winterspring und sprecht mit Umbranse, dem Geistsprecher."}},
[3513] = {"Die runenverzierte Rolle", {"Bringt die runenverzierte Rolle zum nördlichen Wachturm des Brachlandes."}},
[3514] = {"Hordenpräsenz", {"Tötet die Anführerin des Krallenbaus, Rynthariel die Schlüsselmeisterin."}},
[3517] = {"Wissen stehlen", {"Sucht die Schrifttafel von Beth'Amara, die Schrifttafel von Jin'yael, die Schrifttafel von Markri und die Schrifttafel von Sael'hai für Jediga in Valormok."}},
[3518] = {"Lieferung an Magatha Grimmtotem", {"Bringt die Schrifttafel von Beth'Amara zu Magatha Grimmtotem in Thunder Bluff."}},
