[3525] = {"Ausschalten des Götzen", {"Begleitet Belnistrasz zum Götzen der Stacheleber in den Hügeln von Razorfen.","","Beschützt Belnistrasz, während er das Ritual durchführt, um den Götzen auszuschalten."}},
