[3785] = {"Morgenkornforschung", {"Benutzt einen Immergrünbeutel mit einem Paket Tharlendrissamenkörner sowie zwei Un'Goro-Erdproben, um Morgenkorn zu kultivieren.","","Bringt 10 Einheiten Morgenkorn zu Mathrengyl Bearwalker in Darnassus."}},
[3786] = {"Morgenkornforschung", {"Benutzt einen Immergrünbeutel mit einem Paket Tharlendrissamenkörner sowie zwei Un'Goro-Erdproben, um Morgenkorn zu kultivieren.","","Bringt 10 Einheiten Morgenkorn zu Bashana Runetotem in Thunder Bluff."}},
[3789] = {"Erzdruide Staghelm helfen", {"Sprecht mit Erzdruide Fandral Staghelm in Darnassus."}},
[3790] = {"Erzdruide Staghelm helfen", {"Sprecht mit Erzdruide Fandral Staghelm in Darnassus."}},
[3791] = {"Das Geheimnis des Morgenkorns", {"Bringt 10 Einheiten Morgenkorn zu Quintis Jonespyre in der Festung Feathermoon."}},
[3801] = {"Dunkeleisenerbe", {"Sprecht mit Franclorn Forgewright, wenn Ihr daran interessiert seid, einen Schlüssel für die Hauptstadt zu erhalten."}},
[3802] = {"Dunkeleisenerbe", {"Erschlagt Fineous Darkvire und bergt den großen Hammer Ironfel. Bringt Ironfel zum Schrein von Thaurissan und legt ihn auf die Statue von Franclorn Forgewright."}},
[3821] = {"Schreckensfels", {"Begebt Euch in die brennende Steppe und findet heraus, was aus Sha'ni Proudtusk geworden ist."}},
[3822] = {"Krom'Grul", {"Holt Sha'nis Nasenring von Krom'Grul zurück und bringt ihn zu Thal'trak in Kargath. Durchsucht die verschiedenen Höhlen und Minen im Schreckensfels."}},
[3823] = {"Die Feuermagenoger auslöschen", {"Tötet 15 Ogermagier der Feuermägen, 7 Oger der Feuermägen sowie 7 Schläger der Feuermägen und kehrt zu Oralius zurück, wenn Ihr fertig seid."}},
[3841] = {"Waise sucht Zuhause", {"Sprecht mit Quentin in Tausend Nadeln."}},
[3842] = {"Kurz vor dem Schlüpfen", {"Bringt 2 Elixiere der geringen Seelenstärke zu Quentin in Tausend Nadeln."}},
[3843] = {"Das neueste Mitglied der Familie", {"Bringt Euer empfindliches Grimmlingflitzerei ins Hinterland und sprecht mit Agnar Beastamer, aber beeilt Euch. Ihr habt nur eine Stunde Zeit, ihn zu finden. Dann stirbt das Jungtier in dem Ei."}},
[3844] = {"Es ist für jeden ein Geheimnis", {"Sucht in dem Tümpel nach einem Hinweis darauf, wem dieses havarierte Floß gehören könnte."}},
[3845] = {"Es ist für jeden ein Geheimnis", {"Untersucht die Gegenstände in dem Bündel und bringt sie zu ihrem Besitzer."}},
[3861] = {"GLUCK!", {"Beschafft Euch etwas Spezial-Hühnerfutter und kehrt zu dem Huhn zurück, das sich mit Euch angefreundet hat. Wenn Ihr es gefunden habt, dann benutzt erst /cheer, ehe Ihr dem Huhn das Spezial-Hühnerfutter gebt."}},
[3881] = {"Rettungsexpedition", {"Bringt eine Kiste mit Nahrungsmitteln und Forscherausrüstung zu Williden Marshal im Un'Goro Krater."}},
[3882] = {"Knochenklappern", {"Bringt 8 Dinosaurierknochen zu Spark Nilminer im Un'Goro Krater."}},
[3883] = {"Eine fremdartige Ökologie", {"Verwendet die Kratzphiole, um damit eine Schwarmbauwandprobe von einer der Schwarmbrutstätten der Gorishi im Un'Goro Krater zu holen. Sucht nach den Kammern mit der hängenden Larvenbrut.","","Bringt die Schwarmbauwandprobe zu Hol'anyee Marshal im Un'Goro Krater."}},
[3884] = {"Willidens Tagebuch", {"Bringt das Tagebuch zu Williden Marshal zurück. Er befindet sich irgendwo im Un'Goro Krater."}},
[3901] = {"Klappernde Skelette", {"Tötet 12 klappernde Skelette und kehrt zu Schattenpriester Sarvis in Deathknell zurück, wenn Ihr fertig seid."}},
[3902] = {"Beutesuche in Deathknell", {"Durchsucht Deathknell und Umgebung nach 6 Stücken aufgestöberter Ware und bringt sie zu Todeswache Saltain zurück."}},
[3903] = {"Milly Osworth", {"Sprecht mit Milly Osworth."}},
[3904] = {"Millys Ernte", {"Bringt 8 Kisten mit Millys Ernte zu Milly Osworth in der Nähe der Abtei von Nordhain."}},
[3905] = {"Traubenliste", {"Bringt die Traubenliste zu Bruder Neals in der Abtei von Nordhain."}},
[3906] = {"Disharmonie der Flamme", {"Reist zum Steinbruch am Blackrock und tötet Übermeister Pyron. Kehrt zu Thunderheart zurück, sobald Ihr den Auftrag erledigt habt."}},
[3907] = {"Disharmonie des Feuers", {"Betretet die Blackrocktiefen und spürt Lord Incendius auf. Tötet ihn und bringt jegliche Informationsquelle, die Ihr finden könnt, zu Thunderheart."}},
[3908] = {"Es ist für jeden ein Geheimnis", {"Bringt Linkens Schwert zu Donova Snowden in Winterspring."}},
[3909] = {"Das Videre-Elixier", {"Sucht nach Gregan Brewspewer im nördlichen Feralas. Lasst Euch von ihm erklären, wie Ihr Euch das Videre-Elixier beschaffen könnt, und kehrt dann zu Donova Snowden nach Winterspring zurück."}},
[3912] = {"Treffen am Grab", {"Geht zum Friedhof außerhalb von Gadgetzan und benutzt dort das Videre-Elixier. Befolgt Donovas übrige Anweisungen, um Gaeriyan zu finden."}},
[3921] = {"Wenikee Boltbucket", {"Bringt das zerbrochene Samophlang zu Wenikee Boltbucket."}},
[3922] = {"Nugget-Patronen", {"Bringt 15 Nugget-Patronen zu Wenikee Boltbucket im Brachland."}},
[3923] = {"Rilli Greasygob", {"Bringt das zerbrochene Samophlang nach Orgrimmar zu Rilli Greasygob."}},
[3924] = {"Samophlang-Handbuch", {"Bringt das Samophlang-Handbuch nach Orgrimmar zu Rilli Greasygob."}},
[3942] = {"Linkens Andenken", {"Sucht Eridan Bluewind im südlichen Teil des Teufelswalds."}},
[3981] = {"Kommandant Gor'shak", {"Sucht Kommandant Gor'shak in den Blackrocktiefen.","","Ihr erinnert Euch, dass auf dem primitiv gezeichneten Bild des Orcs auch Gitter vor dem Gesicht zu sehen waren. Vielleicht solltet Ihr nach einer Art Gefängnis suchen."}},
[3982] = {"Was ist los?", {"Verteidigt Gor'shak."}},
[4001] = {"Was ist los?", {"Sprecht mit Kharan Mighthammer und sammelt Informationen über die Entführung von Prinzessin Moira Bronzebeard. Bringt diese Informationen dann zu Thrall nach Orgrimmar.","","Ihr erinnert Euch, dass Gor'shak gesagt hat, Kharan werde in einer Zelle in seiner Nähe festgehalten."}},
[4002] = {"Das östliche Königreich", {"Sprecht mit Thrall, wenn Ihr bereit seid, die von ihm geplante Mission zu übernehmen."}},
[4003] = {"Die königliche Rettung", {"Tötet Imperator Dagran Thaurissan und befreit Prinzessin Moira Bronzebeard von seinem bösen Zauber."}},
[4005] = {"Aquementas", {"Bringt das Buch von Aquor, die silbrigen Klauen und das Eisenstammherz nach Tanaris.","","Benutzt das Buch von Aquor, um Aquementas zu beschwören.","","Wenn Ihr das vollständige Totem habt, bringt es zu J.D. Collie in Marshals Zuflucht zurück."}},
[4021] = {"Gegenangriff!", {"Bringt ein Teil von Krom'zars Flagge zu Regthar Deathgate, westlich von Crossroads."}},
[4023] = {"Eine Kostprobe der Flamme", {"Zeigt Cyrus Therepentous einen Beweis für Eure Nützlichkeit.","","Ihr habt so ein Gefühl, dass Cyrus bereits weiß, dass Ihr unwürdig seid."}},
[4024] = {"Eine Kostprobe der Flamme", {"Begebt Euch in die Blackrocktiefen und tötet Bael'Gar.","","Ihr wisst lediglich, dass der Riese irgendwo in den Blackrocktiefen haust. Vergesst nicht, die veränderte Haut des schwarzen Drachenschwarms mit Bael'Gars Überresten zu benutzen und damit die feurige Essenz einzufangen.","","Bringt die eingeschlossene feurige Essenz zu Cyrus Therepentous zurück."}},
[4061] = {"Aufstieg der Maschinen", {"Begebt Euch in die brennende Steppe und beschafft für Theodora Mulvadania 10 gerissene Elementarsplitter.","","Euch fällt ein, dass Theodora gesagt hat, die Golems und Elementare in der Gegend seien eine gute Quelle für solche Splitter."}},
[4062] = {"Aufstieg der Maschinen", {"Bringt die Elementarsplitterprobe zu Lotwil Veriatus.","","Ihr erinnert Euch, dass Theodora sagte, Lotwil sei in einem Lager im Osten stationiert."}},
[4063] = {"Aufstieg der Maschinen", {"Sucht und tötet Golemlord Argelmach. Bringt Lotwil seinen Kopf. Außerdem müsst Ihr 10 intakte Elementarkerne von den Wuthäschergolems und Kriegshetzerkonstrukten, die Argelmach beschützen, beschaffen. Das wisst Ihr, weil Ihr übernatürliche Fähigkeiten habt."}},
[4081] = {"SOFORT TÖTEN: Dunkeleisenzwerge", {"Begebt Euch in die Blackrocktiefen und vernichtet die üblen Aggressoren!","","Kriegsherr Goretooth möchte, dass Ihr 15 Gardisten der Zorneshämmer, 10 Aufseher der Zorneshämmer und 5 Fußsoldaten der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt."}},
[4082] = {"SOFORT TÖTEN: Hochrangige Führungskräfte der Dunkeleisenzwerge", {"Begebt Euch in die Blackrocktiefen und vernichtet die üblen Aggressoren!","","Kriegsherr Goretooth möchte, dass Ihr 10 Sanitäter der Zorneshämmer, 10 Soldaten der Zorneshämmer und 10 Offiziere der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt."}},
[4083] = {"Der spektrale Kelch", nil},
[4084] = {"Silberherz", nil},
[4102] = {"Den Teufelswald säubern", {"Bringt 15 Einheiten Blutharz zu Maybess Riverbreeze im Teufelswald."}},
[4103] = {"Salbe durch Jagd", nil},
[4111] = {"Salbe durch Kürschnerei", nil},
[4115] = {"Verderbte Windblüte", nil},
[4118] = {"Verderbte Liedblume", nil},
[4120] = {"Die Kraft der Verderbnis", {"Talo Thornhoff im Camp Mojache in Feralas möchte, dass Ihr 12 Wutklauengrizzlys und 12 Teufelspfotenverheerer im Teufelswald erledigt."}},
[4121] = {"Gefährliche Zwickmühle", {"Eskortiert Euren Gefangenen, Grark Lorkrub, durch die brennende Steppe und durch den Blackrock in die sengende Schlucht.","","Euch fällt ein, dass Lexlort gesagt hat, seine Männer würden auf der anderen Seite warten, um Grark in Gewahrsam zu nehmen.","","Ihr werdet außerdem Eure Thoriumfesseln an Lexlort übergeben müssen."}},
[4122] = {"Grark Lorkrub", {"Begebt Euch in die brennende Steppe und sucht Grark Lorkrub. Ihr erinnert Euch, dass Lexlort gesagt hat, er sei zuletzt in einer großen Festung der Blackrock gesehen worden.","","Wenn Ihr Grark Lorkrub gefunden habt, verwendet die Thoriumfesseln, um ihn zu binden, und bringt ihn dann über den Blackrock in die sengende Schlucht zurück. Lexlorts Männer werden auf der anderen Seite warten, um Grark in Gewahrsam zu nehmen."}},
[4123] = {"Das Herz des Berges", {"Bringt das 'Herz des Berges' zu Maxwort Uberglint in der brennenden Steppe."}},
[4124] = {"Der vermisste Kurier", {"Sprecht mit Ginro Hearthkindle in der Festung Feathermoon."}},
[4125] = {"Der vermisste Kurier", {"Sucht das Boot des Kuriers irgendwo entlang der Küste von Feralas."}},
[4126] = {"Hurley Pestatem", {"Bringt Ragnar Donnerbräu in Kharanos das gestohlene Donnerbräurezept."}},
[4127] = {"Havarie", {"Kehrt zur Festung Feathermoon zurück und zeigt Ginro Hearthkindle das gefundene Messer."}},
[4128] = {"Ragnar Donnerbräu", {"Sprecht mit Ragnar Donnerbräu."}},
[4129] = {"Das wieder aufgetauchte Messer", {"Bringt Quintis Jonespyre in der Festung Feathermoon das gefundene Messer."}},
[4130] = {"Psychometrie-Sitzung", {"Sprecht mit Ginro Hearthkindle in der Festung Feathermoon."}},
[4131] = {"Die Waldpfotengnolle", {"Durchsucht die Lager der Waldpfotengnolle im Süden Feralas nach Hinweisen auf den Verbleib des Kuriers oder seiner Habseligkeiten."}},
[4132] = {"Operation: Tod dem Zornesschmied", {"Begebt Euch zu den Blackrocktiefen und eliminiert General Zornesschmied! Kehrt zum Kriegsherrn Goretooth zurück, sobald Ihr diese Aufgabe erledigt habt."}},
[4133] = {"Vivian Lagrave", {"Sprecht mit Schattenmeisterin Vivian Lagrave in Kargath."}},
[4134] = {"Verlorenes Donnerbräurezept", {"Bringt Vivian Lagrave in Kargath das gestohlene Donnerbräurezept."}},
[4135] = {"Die verwundene Tiefe", {"Da Ihr jetzt Raschals letzten bekannten Aufenthaltsort in Erfahrung gebracht habt, setzt Ihr die Suche nach ihm oder seinen sterblichen Überresten in der verwundenen Tiefe fort. Laut Notiz soll dieser Ort südlich der Lager der Waldpfotengnolle liegen."}},
[4136] = {"Ribbly Screwspigot", {"Bringt Yuka Screwspigot in der brennenden Steppe Ribblys Kopf."}},
[4141] = {"Muigin und Larion", {"Sammelt 15 Blutblüten und kehrt zu Muigin zurück."}},
[4142] = {"Ein Besuch bei Gregan", {"Bringt Gregan Brewspewer in Feralas eine Blutblüte."}},
[4143] = {"Der Dunst des Bösen", {"Sammelt 5 Proben Dunst der Atal'ai und bringt sie Muigin im Un'Goro Krater."}},
[4144] = {"Blutblütensprösslinge", nil},
