[4224] = {"Die wahren Meister", nil},
[4241] = {"Marshal Windsor", {"Reist zum Blackrock im Nordwesten und dann weiter zu den Blackrocktiefen. Findet heraus, was aus Marshal Windsor geworden ist.","","Ihr erinnert Euch daran, dass der struppige John sagte, man hätte Windsor in ein Gefängnis verschleppt."}},
[4242] = {"Verlorene Hoffnung", {"Überbringt Marshal Maxwell die schlechten Neuigkeiten."}},
[4243] = {"Chasing A-Me 01", {"Sucht im Un'Goro Krater nach A-Me 01."}},
[4244] = {"Chasing A-Me 01", {"Sucht ein Mithrilgehäuse und bringt es zu A-Me 01 im Un'Goro Krater."}},
[4245] = {"Chasing A-Me 01", {"Begleitet A-Me 01 zu Karna Remtravel im Un'Goro Krater."}},
[4261] = {"Alter Geist", {"Bringt Arei in Sicherheit und sprecht dann mit Kayneth Stillwind in Forest Song, im Osten von Ashenvale."}},
[4262] = {"Übermeister Pyron", {"Erschlagt Übermeister Pyron und kehrt dann zu Jalinda Sprig zurück.","","Ihr erinnert Euch an Jalindas Worte, dass Pyron den Steinbruch bewachen würde. Vielleicht solltet Ihr dort nachsehen?"}},
[4263] = {"Incendius!", {"Sucht Lord Incendius in den Blackrocktiefen und vernichtet ihn!"}},
[4264] = {"Eine zusammengeknüllte Notiz", {"Soeben seid Ihr auf etwas gestoßen, das Marshal Windsor mit Sicherheit sehr interessiert. Vielleicht besteht ja doch noch Hoffnung."}},
[4265] = {"Flucht aus dem Schwarmbau", {"Begleitet Raschal sicher aus dem Schwarmbau der Zukk'ash hinaus.","","Kehrt zu Ginro Hearthkindle in der Festung Feathermoon zurück und lasst ihn wissen, dass Raschal am Leben ist und dass es ihm gut geht."}},
[4266] = {"Der Empfang eines Helden", {"Sprecht mit Shandris Feathermoon in der Festung Feathermoon."}},
[4267] = {"Aufstieg der Silithid", {"Bringt Raschals Bericht zu Gracina Spiritmight in Darnassus."}},
[4281] = {"Thalanaar-Lieferung", {"Bringt das nicht ausgelieferte Paket zu Falfindel Waywarder in Thalanaar."}},
[4282] = {"Ein Funken Hoffnung", {"Holt Marshal Windsors verloren gegangene Informationen zurück.","","Marshal Windsor glaubt, dass sich die Informationen in den Händen des Golemlords Argelmach und des Generals Zornesschmied befinden."}},
[4283] = {"FÜNFZIG! Jawoll!", {"Oralius will 50 Medaillons der Blackrock haben. Die Chancen stehen gut, dass man die Medaillons bei den Orcs in der brennenden Steppe findet."}},
[4284] = {"Machtkristalle", {"Sammelt 7 Machtkristalle von jeder Farbe: rot, blau, gelb und grün. Bringt sie zu J. D. Collie in Marshals Zuflucht."}},
[4285] = {"Der Nordpylon", {"Findet den Standort des nördlichen Kristallpylonen im Un'Goro Krater."}},
[4286] = {"Feine Sachen", {"Reist in die Blackrocktiefen und holt 20 Dunkeleisengürteltaschen. Kehrt zu Oralius zurück, sobald die Aufgabe erledigt ist. Ihr nehmt an, dass die Dunkeleisenzwerge in den Blackrocktiefen diese 'Gürteltaschen'-Dinger tragen."}},
[4287] = {"Der Ostpylon", {"Findet den Standort des östlichen Kristallpylonen im Un'Goro Krater."}},
[4288] = {"Der Westpylon", {"Findet den Standort des westlichen Kristallpylonen."}},
[4289] = {"Die Affen von Un'Goro", {"Bringt Torwa Pathfinder am Eingang zum Un'Goro Krater 2 Un'Goro-Gorillapelze, 2 Un'Goro-Stampferpelze und 2 Un'Goro-Donnererpelze."}},
[4290] = {"Lar'korwis Mahl", {"Sucht das Gerippe von Lar'korwis letzter Jagdbeute und stehlt einen Teil eines Dreschadongerippes; kehrt dann zu Torwa Pathfinder im Un'Goro Krater zurück."}},
[4291] = {"Lar'korwis Fährte", {"Bringt Torwa Pathfinder in der Nähe des Eingangs zum Un'Goro Krater 2 Ravasaurus-Pheromondrüsen."}},
[4292] = {"Ein Köder für Lar'korwi", {"Beschwört Lar'korwi mit dem Inhalt von Torwas Beutel und besiegt ihn. Bringt dann Lar'korwis Kopf zu Torwa Pathfinder in der Nähe des Eingangs zum Un'Goro Krater."}},
[4293] = {"Eine Brühschleimerprobe...", {"Sammelt Teufelswaldschleimproben von den Brühschlammern im Teufelswald. Verwendet dann die Testausrüstung neben Chemiker Fuely in Undercity, um zu sehen, welche Eurer Proben am verderbtesten sind. Bringt 5 der verderbten Teufelswaldproben, die Ihr findet, zu Chemiker Fuely."}},
[4294] = {"...und eine Menge Brühschlammer", {"Sammelt Un'Goro-Brühschleimerproben von jedem der Brühschleimer im Un'Goro Krater. Verwendet dann die Testausrüstung neben Chemiker Fuely in Undercity, um zu sehen, welche Eurer Proben am reinsten sind. Bringt 5 der reinen Un'Goro-Proben, die Ihr findet, zu Chemiker Fuely."}},
[4295] = {"Rocknots Bier", nil},
[4296] = {"Schrifttafel der Sieben", {"Bringt Maxwort Uberglint in der brennenden Steppe die Abschrift der Schrifttafel."}},
