[4298] = {"Elternfreuden", {"Sprecht mit Agnar Beastamer im Hinterland."}},
[4300] = {"Knochenklingenwaffen", {"Bringt Jes'rimon in Orgrimmar 8 weiße Ravasaurusklauen."}},
[4301] = {"Der mächtige U'cha", {"Bringt U'chas Pelz zu Torwa Pathfinder am Eingang des Un'Goro Kraters."}},
[4321] = {"Die Sache verstehen", {"Sprecht demnächst mit J. D. Collie."}},
[4322] = {"Gefängnisausbruch!", {"Helft Marshal Windsor, seine Ausrüstung zurückzuholen und seine Freunde zu befreien. Kehrt zu Marshal Windsor zurück, wenn Ihr Erfolg hattet."}},
[4324] = {"Yuka Screwspigot", {"Sprecht mit Yuka Screwspigot in der brennenden Steppe."}},
[4341] = {"Kharan Mighthammer", {"Begebt Euch in die Blackrocktiefen und findet Kharan Mighthammer.","","Der König erwähnte, dass Kharan dort gefangen sei - vielleicht solltet Ihr nach einem Gefängnis Ausschau halten."}},
[4342] = {"Kharans Geschichte", {"Lasst Kharan Mighthammer seine Geschichte erzählen."}},
[4361] = {"Der Überbringer schlechter Botschaften...", {"Kehrt nach Ironforge zurück und überbringt König Magni Bronzebeard die schlechten Nachrichten."}},
[4362] = {"Das Schicksal des Königreichs", {"Kehrt in die Blackrocktiefen zurück und rettet Prinzessin Moira Bronzebeard aus den Fängen des bösen Imperators Dagran Thaurissan."}},
[4363] = {"Die Überraschung der Prinzessin", {"Kehrt nach Ironforge zurück und sprecht mit König Magni Bronzebeard."}},
