[4450] = {"Geschäftsbuch aus Tanaris", {"Nehmt die Abschrift von Goodsteels Geschäftsbuch und beschafft Euch dann die darin aufgeführten Gegenstände, ehe Ihr Krinkle Goodsteel in Tanaris aufsucht."}},
[4451] = {"Der Schlüssel zur Freiheit", {"Sucht in der sengenden Schlucht, bis Ihr etwas findet, wofür man den Schlüssel des Grimsilt-Nebengebäudes verwenden kann, den Ihr gefunden habt."}},
