[4512] = {"Brühschleimer auf Abwegen", {"Bringt 6 mit verfluchten Brühschlammern gefüllte Behälter und 6 mit besudelten Brühschlammern gefüllte Behälter zu Laris Geardawdle in Ironforge."}},
