[4723] = {"Gestrandete Meereskreatur", {"Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde."}},
[4724] = {"Die Herrin der Meute", {"Erschlagt Halycon, die Rudelführerin der Worgs der Blutäxte."}},
