[4729] = {"Kiblers Exotische Tiere", {"Begebt Euch zur Blackrockspitze und sucht Worgwelpen der Blutäxte. Benutzt den Käfig, um die wilden kleinen Bestien zu transportieren. Bringt einen eingesperrten Worgwelpen zu Kibler."}},
[4730] = {"Gestrandete Meereskreatur", {"Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde."}},
