[4737] = {"Auf der Suche nach Menara Voidrender", {"Sprecht mit Menara Voidrender im Brachland."}},
[4738] = {"Auf der Suche nach Menara Voidrender", {"Sprecht im Brachland mit Menara Voidrender."}},
[4739] = {"Auf der Suche nach Menara Voidrender", {"Sprecht mit Menara Voidrender im Brachland."}},
[4740] = {"GESUCHT: Gurgelbacke!", {"Sucht und tötet den Murloc namens Gurgelbacke. Man nimmt an, dass die Kreatur die Hütten der Murlocs am Strand südlich von Auberdine beschützt.","","Informiert Schildwache Glynda Nal'Shea über Gurgelbackes Tod."}},
[4741] = {"Wilde Wächter", {"Trull Failbane im Teufelswald möchte, dass Ihr in Winterspring 13 mondbestrahlte Eulenbestien jagt."}},
[4742] = {"Siegel des Aufstiegs", {"Sucht die drei Edelsteine der Befehlsgewalt: den Edelstein der Gluthauer, den Edelstein der Felsspitzoger und den Edelstein der Blutäxte. Bringt sie zusammen mit dem unverzierten Siegel des Aufstiegs zu Vaelan zurück.","","Vaelan nannte Euch auch die Namen der drei Generäle: Kriegsmeister Voone von den Gluthauern, Hochlord Omokk von den Felsspitzogern und Oberanführer Wyrmthalak von den Blutäxten."}},
[4761] = {"Thundris Windwirker", {"Sprecht mit Thundris Windwirker in Auberdine."}},
[4762] = {"Der Cliffspring", {"Geht von Auberdine aus nach Norden zum ersten Wasserfall des Cliffspring und entnehmt aus dem Teich dort eine Probe.","","Kehrt mit der Cliffspringprobe zu Thundris Windwirker nach Auberdine zurück."}},
[4763] = {"Die verderbten Schwarzfelle", {"Füllt die leere Säuberungsschale am Mondbrunnen in Auberdine.","","Holt jeweils eine Probe von Früchten, Nüssen und Getreide aus dem Lager der Schwarzfellfurbolgs im Norden.","","Mischt alles in der Schale und stellt diese bei dem Freudenfeuer neben dem Cliffspring auf Höhe des nördlichen Lagers ab und lockt dadurch den Satyrverderber an.","","Nehmt den Talisman der Verderbnis und bringt ihn zu Thundris Windwirker in Auberdine."}},
[4764] = {"Doomriggers Schnalle", {"Bringt Mayara Brightwing in der brennenden Steppe Doomriggers Schnalle."}},
[4767] = {"Windreiter", {"Bringt Elu am Freiwindposten 10 Eier von Steilhangflügeldrachen."}},
[4768] = {"Die Darkstone-Schrifttafel", {"Bringt der Schattenmagierin Vivian Lagrave in Kargath die Darkstone-Schrifttafel."}},
[4769] = {"Vivian Lagrave und die Darkstone-Schrifttafel", {"Sprecht mit Schattenmagierin Vivian Lagrave."}},
[4770] = {"Auf der Heimreise", {"Begleitet Pao'ka Swiftmountain aus dem Steilhang heraus und sprecht dann am Weißgipfelposten mit Motega Firemane."}},
[4781] = {"Komponenten für die verzauberte Goldblutrobe", {"Bringt Xizk Goodstitch im Schlingendorntal einen Goldbarren."}},
[4782] = {"Komponenten für die verzauberte Goldblutrobe", {"Kehrt zu Menara Voidrender im Brachland zurück."}},
[4783] = {"Komponenten für die verzauberte Goldblutrobe", {"Bringt Menara Voidrender im Brachland 10 Phiolen Zornsäerblut und 1 geringen Höllenstein."}},
[4784] = {"Komponenten für die verzauberte Goldblutrobe", {"Bringt Menara Voidrender im Brachland Goldgarn, 2 glimmende Kohlen und einen Seelensplitter."}},
[4785] = {"Feiner Goldfaden", nil},
[4786] = {"Die fertig gestellte Robe", {"Wartet, bis Menara Voidrender Eure Robe fertig gestellt hat, und sprecht dann noch einmal mit ihr."}},
[4787] = {"Das uralte Ei", {"Bringt das uralte Ei zu Yeh'kinya nach Tanaris."}},
