[4804] = {"E'ko der Eiswindschimären", nil},
[4808] = {"Felnok Steelspring", {"Gebt Felnok Steelspring Tinkees Brief."}},
[4809] = {"Hörner der Eiswindschimären", {"Bringt Felnok Steelspring 8 unbeschädigte Hörner einer Eiswindschimäre."}},
[4811] = {"Der rote Kristall", {"Reist von Auberdine nach Osten und sucht nach einem großen, roten Kristall entlang der östlichen Bergkette von Dunkelküste. Informiert Schildwache Glynda Nal'Shea in Auberdine über Eure Erkenntnisse."}},
[4812] = {"Wenn das Wasser fließt", {"Füllt die leere Wasserröhre am Mondbrunnen von Auberdine und untersucht dann den roten Kristall an der östlichen Bergkette von Dunkelküste."}},
[4813] = {"Die Fragmente im Inneren", {"Informiert Schildwache Glynda Nal'Shea in Auberdine über Eure Erkenntnisse."}},
[4821] = {"Fremdartiges Ei", {"Bringt Hagar Lightninghoof am Freiwindposten das fremdartige Ei."}},
[4841] = {"Befriedung der Zentauren", {"Tötet 12 Späher der Galak, 10 Zänker der Galak sowie 6 Windjäger der Galak und kehrt dann zu Klippenbehüter Longhorn am Freiwindposten zurück."}},
[4842] = {"Sonderbare Quellen", {"Befolgt Donova Snowdens Anweisungen und meldet Euch dann wieder bei ihr."}},
[4861] = {"Wütende Wildekin", {"Findet Jaron Stoneshapers ruiniertes Lager samt dessen Vorräte im südlichen Winterspring."}},
[4862] = {"Be-Öh-Es-Eh", {"Reist zur Blackrockspitze und sammelt 15 Spitzenspinnen-Eier für Kibler.","","Logischerweise müsstet Ihr diese Eier in der Nähe von Spinnen finden."}},
[4863] = {"Wütende Wildekin", {"Sucht Jaron Stoneshapers zerstörten Wagen."}},
[4864] = {"Wütende Wildekin", {"Klaubt Jarons Vorräte aus dem Schnee und sucht dann die Wildekin, die das Amulett gestohlen haben, von dem Jaron gesprochen hatte.","","Bringt Jaron Stoneshaper in der Lodge in Winterspring dessen Vorräte und das blaugefiederte Amulett."}},
[4865] = {"Wilde Schlange", {"Berichtet Motega Firemane von Euren Entdeckungen."}},
[4866] = {"Muttermilch", {"Ihr findet Mutter Glimmernetz im Herzen der Blackrockspitze. Kämpft mit ihr und bringt sie dazu, Euch zu vergiften. Es kann gut sein, dass Ihr sie sogar töten müsst. Kehrt zum struppigen John zurück, sobald Ihr vergiftet seid, damit er Euch 'melken' kann."}},
[4867] = {"Urok Schreckensbote", {"Lest Waroshs Rolle. Bringt Waroshs Mojo zu Warosh."}},
[4881] = {"Auftragsmordplan", {"Warnt Kanati Greycloud am Weißgipfelposten, dass man vorhat, ihn zu töten."}},
[4901] = {"Wächter des Altars", nil},
[4903] = {"Befehl des Kriegsherrn", {"Tötet Hochlord Omokk, Kriegsmeister Voone und Oberanführer Wyrmthalak. Findet die wichtigen Blackrockdokumente. Kehrt zum Kriegsherrn Goretooth nach Kargath zurück, sobald Ihr diese Mission erledigt habt."}},
[4904] = {"Endlich frei", {"Geleitet Lakota Windsong vom Düsterwolkengipfel hinab und sprecht dann im Freiwindposten mit Thalia Amberhide."}},
[4921] = {"In der Schlacht vermisst", {"Sucht Mankriks Frau und kehrt dann zu ihm nach Crossroads zurück."}},
[4941] = {"Eitriggs Weisheit", {"Sprecht mit Etrigg in Orgrimmar. Wenn Ihr die Angelegenheit mit Etrigg besprochen habt, bittet Thrall um Rat.","","Ihr erinnert Euch, dass Ihr Etrigg in Thralls Gemächern gesehen habt."}},
[4961] = {"Die Säuberung der Kugel von Orahil", {"Tötet den Dämon der Kugel und sprecht dann mit Tabetha."}},
[4962] = {"Splitter eines Teufelshundes", {"Nehmt den Felhas-Rubin und benutzt ihn bei einem der Teufelshunde von Desolace. Wenn Ihr Erfolg hattet, bringt Menara Voidrender im Brachland den eingekerkerten Teufelshundgeist und den Felhas-Rubin."}},
[4963] = {"Splitter einer Höllenbestie", {"Nehmt den Infus-Smaragd und benutzt ihn bei einer der Höllenbestien von Desolace. Wenn Ihr Erfolg hattet, bringt Menara Voidrender im Brachland den eingekerkerten Höllenbestiengeist und den Infus-Smaragd."}},
[4964] = {"Die fertig gestellte Kugel von Dar'Orahil", {"Wartet, bis Menara Voidrender die Kugel von Dar'Orahil fertig gestellt hat, und sprecht dann noch einmal mit ihr."}},
[4965] = {"Wissen der Kugel von Orahil", {"Sprecht mit Menara Voidrender im Brachland."}},
[4966] = {"Kanati Greycloud schützen", {"Beschützt Kanati Greycloud vor den Angriffen der Zentauren."}},
[4967] = {"Wissen der Kugel von Orahil", {"Sprecht mit Menara Voidrender im Brachland."}},
[4968] = {"Wissen der Kugel von Orahil", {"Sprecht mit Menara Voidrender im Brachland."}},
[4969] = {"Wissen der Kugel von Orahil", {"Sprecht mit Menara Voidrender im Brachland."}},
[4971] = {"Eine Frage der Zeit", {"Benutzt den Temporalversetzer in der Nähe eines der Silos von Andorhal, um die temporalen Parasiten aufzuspüren.","","Tötet 15 temporale Parasiten und bringt dann den Temporalversetzer zu Chromie im Gasthaus Andorhal in den Westlichen Pestländern."}},
[4972] = {"Tempus fugit", {"Sucht 5 Andorhal-Uhren, die in Schließkassetten überall im Schutt der Stadt zu finden sind. Kehrt mit ihnen zu Chromie ins Gasthaus Andorhal in den Westlichen Pestländern zurück."}},
[4973] = {"Tempus fugit", nil},
[4974] = {"Für die Horde!", {"Begebt Euch zur Blackrockspitze und tötet den Kriegshäuptling Rend Blackhand. Nehmt seinen Kopf und kehrt nach Orgrimmar zurück."}},
[4975] = {"Die fertig gestellte Kugel von Noh'Orahil", {"Wartet, bis Menara Voidrender die Kugel von Noh'Orahil fertig gestellt hat, und sprecht dann noch einmal mit ihr."}},
[4976] = {"Ablieferung der gesäuberten Kugel", {"Bringt die gesäuberte Höllenkugel zu Menara Voidrender ins Brachland."}},
[4981] = {"Agentin Bijou", {"Begebt Euch zur Blackrockspitze und findet heraus, was aus Bijou geworden ist."}},
[4982] = {"Bijous Habseligkeiten", {"Sucht Bijous Habseligkeiten und bringt sie ihr. Ihr erinnert Euch daran, dass sie erwähnte, ihre Sachen auf der untersten Ebene der Stadt versteckt zu haben."}},
[4983] = {"Bijous Aufklärungsbericht", {"Bringt Bijous Aufklärungsbericht zu Großmeister Lexlort nach Kargath."}},
[4984] = {"Die Tierwelt leidet auch", {"Tötet 8 kranke Wölfe und kehrt dann zu Mulgris Deepriver auf dem trostlosen Feld in den Westlichen Pestländern zurück."}},
[4985] = {"Die Tierwelt leidet auch", {"Tötet 8 kranke Grizzlys und kehrt dann zu Mulgris Deepriver auf dem trostlosen Feld in den Westlichen Pestländern zurück."}},
[4987] = {"Glyphenverzierter Eichenast", {"Nach der Magie zu urteilen, mit der der glyphenverzierte Eichenast erfüllt ist, hatte der Taurendruide wohl gewollt, dass Ihr den Ast zum Zirkel des Cenarius nach Thunder Bluff bringt. Bittet einen der Druiden dort um Hilfe."}},
[5021] = {"Besser spät als nie", {"Das wilde Gebrabbel der Geisterfrau deutete darauf hin, dass sie ein Paket ausliefern musste. Sie behauptete, dass es dort war, wo auch ihr Pferd war. Darüber, wo das Pferd jetzt ist oder wohin das Paket ausgeliefert werden muss, sagt der Geist nichts."}},
[5022] = {"Besser spät als nie", {"Wendet Euch an die königlichen Disponenten von Stormwind, um etwas über den Aufenthaltsort von Emma Felstone herauszufinden. Normalerweise findet sich ein Volkszählungsbeamter im Rathaus."}},
[5023] = {"Besser spät als nie", {"Wendet Euch an die königlichen Vorarbeiter von Undercity, um etwas über den Aufenthaltsort von Jeremiah Felstone herauszufinden. Normalerweise findet sich ein Volkszählungsbeamter in der Nähe der Gilden- und Wappenrock-Registrierung."}},
[5041] = {"Vorräte für Crossroads", {"Findet die Crossroads-Vorratskisten und bringt sie zu Thork im Brachland zurück."}},
[5042] = {"Agammagans Kraft", nil},
[5043] = {"Agammagans Beweglichkeit", nil},
[5044] = {"Weisheit von Agammagan", nil},
[5045] = {"Steigerung des Geistes", nil},
[5046] = {"Klingenhaut", nil},
[5048] = {"Emma die Nette", {"Sucht die alte Emma in Stormwind und findet heraus, ob sie tatsächlich Emma Felstone ist. Wenn sie es ist, dann möchte sie vielleicht das Paket haben, das Janice Felstone für sie gepackt hat."}},
[5049] = {"Der Jammer des Jeremiah", {"Sucht Jeremiah Payson in Undercity und findet heraus, ob er tatsächlich Jeremiah Felstone ist. Wenn er es ist, dann möchte er vielleicht das Paket haben, das Janice Felstone für ihn gepackt hat."}},
[5050] = {"Glücksbringer", {"Bringt Janice Felstone in den Westlichen Pestländern die Hälfte ihres Glücksbringers zurück."}},
[5051] = {"Zwei Hälften vereint", {"Sucht auf dem Teufelssteinfeld in den Westlichen Pestländern nach der anderen Hälfte des Glücksbringers und setzt ihn wieder zusammen.","","Gebt den Glücksbringer Janice Felstone auf demTeufelssteinfeld in den Westlichen Pestländern."}},
[5052] = {"Blutsplitter von Agammagan", {"Bringt Quetschzahn im Camp Taurajo im Brachland einen Blutsplitter.","","Sammelt weitere Blutsplitter, wenn Ihr von ihm mit Agammagans Macht gesegnet werden möchtet."}},
[5054] = {"Ursius von den Splitterzahnbären", {"Storm Shadowhoof in Everlook in Winterspring möchte, dass Ihr Ursius tötet."}},
[5055] = {"Brumeran von den Eiswindschimären", {"Storm Shadowhoof in Everlook in Winterspring möchte, dass Ihr Brumeran tötet."}},
[5058] = {"Mrs. Dalsons Tagebuch", nil},
[5059] = {"Weggeschlossen", nil},
[5060] = {"Weggeschlossen", nil},
[5061] = {"Wassergestalt", {"Kehrt nach Darnassus zurück und zeigt Mathrengyl Bearwalker den Anhänger des Seelöwen."}},
[5062] = {"Hochheiliges Feuer", {"Sammelt 10 Scheffel Brandpulveragaven und beratet Euch dann mit Magatha Grimmtotem auf der Anhöhe der Ältesten in Thunder Bluff."}},
[5064] = {"Grimmtotemspionage", {"Sucht die drei geheimen Notizen im Düsterwolkengipfel und bringt sie zurück."}},
[5065] = {"Die verlorenen Schrifttafeln von Mosh'aru", {"Bringt Ausgrabungsleiter Ironboot in Tanaris die dritte und vierte Schrifttafel von Mosh'aru."}},
[5066] = {"Der Ruf zu den Waffen: Die Pestländer!", {"Sucht Kommandant Ashlam Valorfist auf. Sein Stützpunkt befindet sich an der Chillwindspitze, nördlich des Alteracgebirges."}},
[5082] = {"Bedrohung durch die Winterfelle", {"Donova Snowden in Winterspring möchte, dass Ihr 8 Pfadfinder der Winterfelle, 8 Höhlenbehüter der Winterfelle und 8 Totemiker der Winterfelle erledigt."}},
[5083] = {"Feuerwasser der Winterfelle", {"Bringt das leere Feuerwasserfläschchen zu Donova Snowden in Winterspring."}},
[5084] = {"Der Verderbnis erliegen", {"Durchsucht das Furbolglager der Totenwaldfelle im nördlichen Teil des Teufelswalds nach einem Hinweis."}},
[5086] = {"Toxinschrecken", {"Sammelt 3 Toxinschrecken-Tröpfchen für Donova Snowden in Winterspring."}},
[5088] = {"Arikara", {"Tötet Arikara. Bringt ihre Überreste und das Brandpulver zu Motega Firemane im Weißgipfelposten als Beweis für Eure Taten."}},
[5090] = {"Der Ruf zu den Waffen: Die Pestländer!", {"Sucht Kommandant Ashlam Valorfist auf. Sein Stützpunkt befindet sich an der Chillwindspitze, nördlich des Alteracgebirges."}},
[5091] = {"Der Ruf zu den Waffen: Die Pestländer!", {"Sucht Kommandant Ashlam Valorfist auf. Sein Stützpunkt befindet sich an der Chillwindspitze, nördlich des Alteracgebirges."}},
[5092] = {"Den Weg räumen", {"Tötet 10 Skelettschinder und 10 sabbernde Ghuls in Sorrow Hill.","","Kehrt zu Kommandant Ashlam Valorfist an der Chillwindspitze, Westliche Pestländer, zurück."}},
[5093] = {"Der Ruf zu den Waffen: Die Pestländer!", {"Sucht Hochexekutor Derrington auf. Sein Stützpunk befindet sich am Bollwerk, östlich von Tirisfal und Undercity."}},
[5094] = {"Der Ruf zu den Waffen: Die Pestländer!", {"Sucht Hochexekutor Derrington auf. Sein Stützpunk befindet sich am Bollwerk, östlich von Tirisfal und Undercity."}},
[5095] = {"Der Ruf zu den Waffen: Die Pestländer!", {"Sucht Hochexekutor Derrington auf. Sein Stützpunk befindet sich am Bollwerk, östlich von Tirisfal und Undercity."}},
[5096] = {"Scharlachrote Ablenkung", {"Zieht zum Basislager des Scharlachroten Kreuzzugs zwischen dem Teufelssteinfeld und Dalsons Tränenfeld und zerstört sein Kommandozelt.","","Lasst das Banner der Geißel im Lager wehen und kehrt dann zu Hochexekutor Derrington am Bollwerk in den Westlichen Pestländern zurück."}},
[5097] = {"Turm um Turm", {"Markiert mit der Signalfackel jeden Turm in Andorhal; Ihr müsst im Eingang jedes Turmes stehen, um ihn erfolgreich zu markieren.","","Wenn alle vier Türme markiert sind, bringt Ihr die Signalfackel zu Kommandant Ashlam Valorfist an der Chillwindspitze, Westliche Pestländer, zurück."}},
[5098] = {"Turm um Turm", {"Markiert mit der Signalfackel jeden Turm in Andorhal; Ihr müsst im Eingang jedes Turmes stehen, um ihn erfolgreich zu markieren.","","Wenn alle vier Türme markiert sind, bringt Ihr die Signalfackel zu Hochexekutor Derrington am Bollwerk, Westliche Pestländer, zurück."}},
[5121] = {"Oberhäuptling der Winterfelle", {"Donova Snowden in Winterspring möchte, dass Ihr den Oberhäuptling der Winterfelle besiegt."}},
[5142] = {"Klein-Pamela", {"Sucht Pamela Redpath."}},
[5145] = {"Drachenlederverarbeitung", {"Bringt 2 feste Skorpidbrustplatten, 2 feste Skorpidhandschuhe und 10 Drachenschuppen zu Thorkaf Dragoneye im Ödland.","","Wenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Drachenlederverarbeitung erhalten.","","Ihr könnt dann allerdings weder Elementarlederverarbeitung noch Stammeslederverarbeitung erlernen; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt."}},
[5146] = {"Elementarlederverarbeitung", nil},
[5147] = {"GESUCHT: Arnak Grimmtotem", {"Erschlagt Arnak Grimmtotem und bringt den Beweis Eurer Tat zu Klippenbehüter Longhorn im Freiwindposten."}},
[5149] = {"Pamelas Puppe", {"Sucht Pamelas Puppe."}},
[5150] = {"Dadanga ist hungrig!", nil},
[5151] = {"Hyperkondensator-Dingsda", {"Erschlagt die Bestie und bringt den Hyperkondensator sowie den Pantherkäfigschlüssel zu Wizlo Bearingshiner zurück."}},
[5152] = {"Tante Marlene", {"Sprecht mit Marlene, südlich der Ruinen von Andorhal."}},
[5153] = {"Ein seltsamer Historiker", {"Bringt Josephs Ehering zu Chromie."}},
[5154] = {"Die Annalen von Darrowshire", {"Bringt die 'Annalen von Darrowshire' zu Chromie in Andorhal."}},
[5155] = {"Streitmacht von Jaedenar", {"Betretet Jaedenar und erschlagt 4 Hunde von Jaedenar, 4 Gardisten von Jaedenar, 6 Adepten von Jaedenar und 6 Kultisten von Jaedenar, bevor Ihr zu Greta Mosshoof im Teufelswald zurückkehrt."}},
[5156] = {"Die Verderbnis überprüfen", {"Sucht und zerstört 2 entropische Bestien und 2 entropische Schrecken, während Ihr das Shatter Scar-Tal erforscht. Nachdem Ihr überprüft habt, ob die Krater immer noch mit verderbtem Fel-Wasser gefüllt sind, kehrt zu Taronn Redfeather im Teufelswald zurück."}},
[5157] = {"Verderbtes Wasser sammeln", {"Bringt die leere Feldflasche zum Mondbrunnen im Zentrum von Jaedenar und füllt sie, bevor Ihr zu Greta Mosshoof im Teufelswald zurückkehrt."}},
[5158] = {"Spirituelle Hilfe suchen", {"Bringt das verderbte Mondbrunnenwasser in das Brachland zu Islen Waterseer."}},
[5159] = {"Gesäubertes Wasser wird zum Teufelswald gebracht", {"Bringt das geläuterte Mondbrunnenwasser zu Greta Mosshoof im Teufelswald."}},
[5163] = {"Sind wir endlich da, Yeti?", {"Nehmt Umis mechanischen Yeti und erschreckt ihre Freunde damit:","","Legacki in Everlook (Winterspring)","Sprinkle in Gadgetzan (Tanaris)","Quixxil in Marshals Zuflucht (Un'Goro Krater)","","Wenn Ihr damit fertig seid, bringt den mechanischen Yeti zu Umi zurück."}},
[5165] = {"Übergießen der Flammen des Schutzes", {"Übergießt die Flammen der vier Kohlenpfannen des Schutzes in der Schattenfeste im Teufelswald mit dem geläuterten Mondbrunnenwasser."}},
[5168] = {"Helden von Darrowshire", nil},
[5181] = {"Bösewichte von Darrowshire", nil},
[5202] = {"Ein merkwürdiger roter Schlüssel", {"Durchsucht Jaedenar, um herauszufinden, wofür der blutrote Schlüssel verwendet wird."}},
[5203] = {"Rettung aus Jaedenar", {"Bringt Arko'narin dorthin, wo Lightforge und ihre Ausrüstung aufbewahrt werden, und beschützt sie dann bei eurer Flucht aus der Schattenfeste. Sucht danach Jessir Moonbow im Teufelswald auf und lasst sie wissen, was mit ihren Freunden geschehen ist."}},
[5204] = {"Vergeltung des Lichts", {"Kehrt nach Jaedenar zurück und tötet den Sukkubus Rakaiah, bevor Ihr die Überreste von Trey Lightforge sucht."}},
[5211] = {"Verteidiger von Darrowshire", {"Befreit 15 Geister von Darrowshire und kehrt dann zu Carlin Redpath zurück."}},
[5212] = {"Das Fleisch lügt nicht", {"Sammelt 20 verseuchte Fleischproben in Stratholme und bringt sie zu Betina Bigglezink zurück. Ihr vermutet, dass Ihr besagte Fleischproben bei jeder Kreatur in Stratholme finden könnt."}},
[5214] = {"Der große Ezra Grimm", {"Sucht Ezra Grimms Raucherladen in Stratholme und bergt einen Kasten von Grimms Tollem Tabak. Kehrt zu Smokey LaRue zurück, wenn Eure Aufgabe erledigt ist."}},
[5215] = {"Die Geißelkessel", {"Sprecht mit der Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer."}},
[5216] = {"Ziel: Teufelssteinfeld", {"Geht zum Teufelssteinfeld im den Westlichen Pestländern. Sucht nach dem dortigen Kessellord und besiegt ihn. Er könnte einen Schlüssel haben, der den Zugang zu dem Kessel ermöglicht. Ihr müsst die leere Flasche: Teufelssteinfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet."}},
[5217] = {"Rückkehr zum Chillwind-Lager", {"Bringt die gefüllte Flasche: Teufelssteinfeld zur Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer."}},
[5219] = {"Ziel: Dalsons Tränenfeld", {"Begebt Euch zu Dalsons Tränenfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Dalsons Tränenfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet."}},
[5220] = {"Rückkehr zum Chillwind-Lager", {"Bringt die gefüllte Flasche: Dalsons Tränenfeld zur Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer."}},
