[5763] = {"Jagd im Schlingendorntal", {"Bringt Roons Kodohorn zu Hemet Nesingwary ins Schlingendorntal."}},
[5802] = {"Feuerfeder geschmiedet", {"Bringt die Skelettschlüsselform und 2 Barren Thorium zur Spitze des Feuerfedergrats im Un'Goro Krater. Benutzt die Skelettschlüsselform am Lavasee, um den unvollendeten Skelettschlüssel zu schmieden.","","Bringt den unvollendeten Skelettschlüssel zu Apotheker Dithers im Bollwerk, Westliche Pestländer."}},
[5804] = {"Arajs Skarabäus", {"Vernichtet Araj den Beschwörer und bringt Arajs Skarabäus zum Apotheker Dithers im Bollwerk, in den westlichen Pestländern."}},
[5821] = {"Leibwache zu mieten", {"Bringt Gizeltons Karawane am Dorf der Kolkarzentauren vorbei. Sprecht in Scrabblescrews Lager mit Smeed, um Eure Belohnung zu erhalten."}},
[5848] = {"Von Liebe und Familie", {"Begebt Euch nach Stratholme im nördlichen Teil der Pestländer. In der Scharlachroten Bastion findet Ihr das Gemälde 'Von Liebe und Familie', das zwischen anderen Gemälden versteckt ist und auf dem die Zwillingsmonde unserer Welt abgebildet sind.","","Bringt das Gemälde zu Tirion Fordring."}},
[5863] = {"Das Truppenlager der Dünenbrecher", {"Andi Lynn in Gadgetzan möchte, dass Ihr das Truppenlager der Dünenbrecher vernichtet, indem Ihr 10 Schläger der Dünenbrecher 10 Vollstrecker der Dünenbrecher sowie Gor'marok den Verheerer tötet."}},
