[6001] = {"Körper und Herz", {"Benutzt den Mondstaub des Cenarius mit dem Moonkinstein, um Mondklaue herauszulocken. Danach müsst Ihr Euch Mondklaue stellen und Euch die Kraft des Körpers und des Herzens verdienen, die er besitzt.","","Sprecht mit Mathrengyl Bearwalker in Darnassus, wenn Ihr fertig seid."}},
[6002] = {"Körper und Herz", {"Benutzt den Lunarstaub des Cenarius mit dem Moonkinstein, um Mondklaue herauszulocken. Danach müsst Ihr Euch Mondklaue stellen und Euch die Kraft des Körpers und des Herzens verdienen, die er besitzt.","","Sprecht mit Turak Runetotem in Thunder Bluff, wenn Ihr fertig seid."}},
[6004] = {"Offene Rechnungen", {"Tötet 2 scharlachrote Sanitäter, 2 scharlachrote Jäger, 2 scharlachrote Magi und 2 scharlachrote Ritter, bevor Ihr zu Kirsta Deepshadow in den Westlichen Pestländern zurückkehrt."}},
