[6022] = {"Töten zu einem bestimmten Zweck", {"Begebt Euch zu Corins Kreuzung im Osten und besiegt die Mitglieder der Geißel, die in der Stadt leben. Sammelt 7 Stücke lebendige Fäulnis in unter 10 Minuten. Zerstoßt die lebendige Fäulnis mit Mörser und Stößel zu geronnener Fäulnis."}},
[6023] = {"Offene Rechnungen", {"Besiegt Jägerin Radley und Chevalier Durgen, bevor Ihr zu Kirsta Deepshadow in den Westlichen Pestländern zurückkehrt."}},
[6024] = {"Hameyas Bitte", {"Tötet Spitzel Hameya. Benutzt seinen Schlüssel bei dem Erdhaufen hinter dem Tiefgewölbe."}},
[6025] = {"Offene Rechnungen", {"Geht nach Hearthglen, sucht einen hohen Aussichtspunkt, von dem aus Ihr die Stadt überblicken könnt, schätzt die Streitkräfte des Scharlachroten Kreuzzugs und kehrt dann zu Kirsta Deepshadow in den Westlichen Pestländern zurück."}},
[6026] = {"Das ist viel verlangt", {"Smokey LaRue möchte, dass Ihr 2 Thoriumbarren, 1 Goldrute, 8 hochexplosive Bomben und 8 instabile Auslöser beschafft.","","Für diese Gegenstände müsst Ihr einen Schmied und einen Ingenieur finden."}},
