[7828] = {"Die Pirsch auf die Pirscher", {"Jäger Markhor aus Revantusk im Hinterland möchte, dass Ihr 15 Silbermähnenpirscher und 15 Silbermähnenheuler tötet. Kehrt zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt.","","Markhor erwähnte, dass sich die Wölfe in der Wildnis des Hinterlands verstecken."}},
[7829] = {"Jagt die Wilden", {"Jäger Markhor aus Revantusk im Hinterland möchte, dass Ihr 20 Wilde Eulenbestien tötet. Kehrt zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt.","","Markhor erwähnte, dass sich die Eulenbestien in der Wildnis des Hinterlands befinden."}},
[7830] = {"Die Gefallenen rächen", {"Jäger Markhor aus Revantusk im Hinterland möchte, dass Ihr einen Klingenschnabelhimmelsfürsten tötet und dessen Federbusch an Euch nehmt. Kehrt zu ihm zurück sobald Ihr diese Aufgabe erledigt habt.","","Die Klingenschnabelhimmelsfürsten sind eine recht seltene Spezies und nisten meist in der Wildnis des Hinterlands."}},
