[7839] = {"Schläger der Vilebranch", {"Schmied Slagtree aus Revantusk im Hinterland möchte, dass Ihr seine verlorenen Werkzeuge ausfindig macht und dann zu ihm zurückkehrt.","","Ihr erinnert Euch an Schmied Slagtrees Worte, dass die Werkzeuge möglicherweise bei einem der Tempel der Vilebranch zu finden seien, im Nordosten des Hinterlands. Ihr solltet auch Skulk Rock absuchen."}},
[7840] = {"Lards vergessene Brotzeit", {"Lard aus Revantusk im Hinterland möchte, dass Ihr Lards Brotzeit wieder findet. Kehrt nach Erfüllung dieser Aufgabe zu ihm zurück.","","Lard erwähnte, dass er es auf der Insel im Norden vergessen habe. Achtet auf die Trolle der Vilebranch."}},
[7841] = {"Eine Botschaft an die Wildhammer", {"Otho Moji'ko aus Revantusk im Hinterland möchte, dass Ihr 15 Hochtalkundschafterinnen, 15 Hochtalspäher, 15 Hochtalschützen und 15 Hochtalwaldläuferinnen tötet. Kehrt nach vollendeten Taten zu ihm zurück.","","Ihr findet die Hochtalelfen bei der Jagdhütte Quel'Danil im Nordwesten des Hinterlands."}},
[7842] = {"Eine weitere Botschaft an die Wildhammer", {"Otho Moji'ko aus Revantusk im Hinterland möchte, dass Ihr ihm 10 lange elegante Federn von Greifen besorgt, die das Hinterland bewohnen. Kehrt mit den Federn zu ihm zurück.","","Es ist bekannt, dass Greifen überall im Hinterland zu finden sind."}},
[7843] = {"Die letzte Botschaft an die Wildhammer", {"Otho Moji'ko aus Revantusk im Hinterland möchte, dass Ihr zum Aerie Peak im Westen des Hinterlands reist und die letzte Botschaft an die Wildhammer beim Brunnen im Stadtzentrum platziert. Kehrt nach Vollendung der Aufgabe zu ihm zurück.","","Hütet Euch vor zornigen Wildhammer-Zwergen und niederträchtigen Mitgliedern der Allianz."}},
[7844] = {"Kannibalistische Vettern", {"Mystikerin Yayo'jin aus Revantusk im Hinterland möchte, dass Ihr 30 Skalpierer der Vilebranch und 15 Sterndeuter der Vilebranch tötet. Kehrt nach Vollendung dieser Aufgabe zu ihr zurück.","","Yayo'jin deutete an, dass man diese Trolle nahe der Tempel von Shaol'watha und Agol'watha finden könnte. Sie liegen im Nordosten des Hinterlands."}},
[7845] = {"Die Entführung des Älteren Torntusk", {"Primal Torntusk aus Raventusk im Hinterland möchte, dass Ihr ihren Gefährten, den Älteren Torntusk, aus Jintha'Alor befreit.","","Man sagte Euch, dass er hoch oben in Jintha'Alor gefangen gehalten wird - der Hauptstadt der Vilebranch im Süden des Hinterlands."}},
[7846] = {"Erlangt den Schlüssel!", {"Der Ältere Torntusk in Jintha'Alor möchte, dass Ihr Hitah'ya die Bewahrerin tötet, um in den Besitz des Fesselnschlüssels zu kommen. Kehrt zum Älteren Torn'tusk zurück, wenn Ihr den Schlüssel habt."}},
[7847] = {"Rückkehr zu Primal Torntusk", {"Der Ältere Torntusk in Jintha'Alor möchte, dass Ihr Primal Torntusk in Revantusk die Neuigkeit von seiner Befreiung überbringt."}},
[7849] = {"Die getrennten Brüder", {"Jäger Markhor aus Revantusk im Hinterland möchte, dass Ihr die Überreste seines Zwillingsbruders bergt. Findet den Schädel und die Knochen des Jägers Malkhor und bringt sie zu Jäger Markhor zurück.","","Markhor erwähnte, dass die Überreste seines Bruders an die Brühschlammer und Wölfe der Vilebranch verfüttert wurden. Er sagte weiterhin, dass es in Jintha'Alor eine Grube mit Brühschlammern gibt, sowie einen Wolfsbau. Beide liegen in der Nähe der Tempelspitze."}},
[7850] = {"Dunkle Gefäße", {"Primal Torntusk aus Revantusk im Hinterland möchte, dass Ihr Euch 10 Gefäße mit besudeltem Blut aus Jintha'Alor beschafft. Kehrt dann damit zu Primal Torntusk zurück."}},
[7861] = {"GESUCHT: Üble Priesterin Hexx und ihre Diener", {"Ihr habt die Anweisung erhalten die üble Priesterin Hexx und 20 Aman'zasiwachen der Vilebranch zu töten. Habt Ihr Eure Aufgabe erfüllt, so sprecht mit Primal Torntusk aus Revantusk im Hinterland.","","Die üble Priesterin Hexx und die Aman'zasiwachen halten sich hoch oben in Jintha'Alor im Hinterland auf."}},
[7862] = {"Offener Posten: Wachbefehlshaber von Revantusk", {"Ihr wurdet mit der Vernichtung von 20 Berserkern der Vilebranch, 20 Schattenjägern der Vilebranch, 20 Bluttrinkern der Vilebranch und 20 Seelenfressern der Vilebranch beauftragt.","","Kehrt nach Beendigung dieser Aufgabe zu Primal Torntusk aus Revantusk im Hinterland zurück."}},
