[92893] = {"Keine Gnade den Schwachen", {"Wahrt Euren Ruf bei den Magram und tötet 5 Gefangene der Gelkis im ganzen Tal der Knochen. Kehrt danach zu Orgrul zurück."}},
[92894] = {"Gebeinerweckung", {"Wahrt Euren Ruf bei den Magram und nutzt den verbesserten Stab der Totenbeschwörung, um Untote, die sich im Tal der Knochen nicht erheben können, vollständig zu erwecken. Kehrt zu Orgrul zurück, nachdem das Heer der Magram Zuwachs erhalten hat."}},
[92909] = {"Die Ernter ernten", {"Ozwin Ironsprocket auf Saldeans Hof möchte, dass Ihr ihm 14 Golemisofedern und 5 Gyrostabilisatoren für Erntearbeiter bringt."}},
[92910] = {"Die Ernter ernten", {"Bringt die Präzessions-Autokognitions-Einheit zu Ozwin Ironsprocket auf Saldeans Hof."}},
[92911] = {"Die Ernter ernten", {"Ozwin Ironsprocket auf Saldeans Hof möchte, dass Ihr ihm 8 Golemisofedern, 4 Kupfermodulatoren und ein kunstloses Zielfernrohr bringt."}},
[92914] = {"Seltsame Pylonen", {"Erkundet Shen'dralas, um andere Pylonen wie den zu finden, den ihr bereits gefunden habt."}},
[92947] = {"Unser Aufbruch", {"Tötet 7 Wächter der Al'Aketh, 7 Geistrufer der Al'Aketh und 7 Klingenmeister der Al'Aketh, und erstattet anschließend Hyusaa Quickbreeze beim Schrein von Akir Bericht."}},
[92959] = {"Die sterbenden Urtume", {"Spürt das verderbte Urtum Rindenriss auf, vernichtet es und pflanzt dann einen Samen in seinen Überresten."}},
[92960] = {"Entzogene ephemere Essenz", {"Beschafft 6 ephemere Essenzen für Elaena Moonwhisper."}},
[93016] = {"Eine kurze Geschichtsstunde", {"Sprecht mit Mordent Evenshade in Shen'dralas, um Informationen zu den Kristallen zu erhalten, die Ihr repariert habt."}},
[93034] = {"Tal der Knochen", {"Verbessert Euren Ruf bei den Gelkis und sucht Nerlokh in der Nähe des Tals der Knochen auf, das weit östlich vom Dorf Gelkis liegt."}},
[93035] = {"Verwüstende Verheerer", {"Wahrt Euren Ruf bei den Gelkis und tötet 6 untote Verheerer. Kehrt dann zu Nerlokh am südlichen Eingang zum Tal der Knochen zurück."}},
[93036] = {"Den Kult infiltrieren", {"Sprecht mit Sania Silverstream in Shen'dar."}},
[93037] = {"Aufgedeckte Außenseiter", {"Wahrt Euren Ruf bei den Gelkis und bringt 1 nekromantische Gewänder zu Nerlokh am Eingang zum Tal der Knochen."}},
[93041] = {"Im Angesicht der Wahrheit", {"Wahrt Euren Ruf bei den Gelkis und bringt einen verfluchten Schädel sowie nekromantische Gewänder der Gelkis zu Uthek der Weisen im Dorf Gelkis."}},
[93044] = {"Ein reinigender Schrei", {"Wahrt Euren Ruf bei den Gelkis und bringt Tränen von Theradras zu Uthek der Weisen im Dorf Gelkis in Desolace."}},
[93045] = {"Die Probe aufs Exempel", {"Wahrt Euren Ruf bei den Gelkis und hebt den nekromantischen Fluch auf, der auf dem verfluchten Schädel lastet. Wenn Ihr erfolgreich wart, meldet Euch bei Nerlokh in der Nähe des Tals der Knochen zurück."}},
[93058] = {"Die Eigenen retten", {"Wahrt Euren Ruf bei den Gelkis und rettet 5 Gefangene der Gelkis im Tal der Knochen. Kehrt dann zu Nerlokh beim Eingang zurück."}},
[93062] = {"Gebeinbestattung", {"Wahrt Euren Ruf bei den Gelkis und entzaubert die Flüche von 8 fehlgeschlagenen Beschwörungen im gesamten Tal der Knochen."}},
[93065] = {"Bereit für die Schlacht", {"Sprecht mit Valanaar Stormfist im Böenbeerentiefland."}},
[93066] = {"Rückzugsort der Borstennacken", {"Wahrt Euren Ruf bei den Magram und tötet Stacheleber im Rückzugsort der Borstennacken. Meldet Euch dann bei Hagiak an der Front der Magram auf der anderen Seite des Tals der Knochen in Desolace."}},
[93072] = {"Langzeitlösungen", {"Wahrt Euren Ruf bei den Magram und tötet 2 ausgestoßene Späher, 6 ausgestoßene Marodeure und 8 ausgestoßene Totenbeschwörer. Kehrt dann zu Hagiak an die Front der Magram zurück."}},
[93089] = {"Was kommt als Nächstes", {"Sprecht mit Elaadrin Evengale, wenn Ihr bereit seid, die Insel Zephras zu verlassen."}},
[93090] = {"Nächste Schritte", {"Sprecht mit Ayessa Dawnsinger, wenn Ihr bereit seid, die Insel Zephras zu verlassen."}},
[93122] = {"Die Dinge überprüfen", {"Wahrt Euren Ruf bei den Gelkis und untersucht Knotenpunkte der Zentrauren innerhalb von Shen'dralas. Kehrt mit Euren Erkenntnissen zu Nerlokh am Eingang zum Tal der Knochen zurück."}},
[93125] = {"Auf nach Hause", {"Wahrt Euren Ruf bei den Gelkis und begleitet Rokren aus der Zuflucht der Ausgestoßenen. Berichtet dann Nerlokh in der Nähe des Tals der Knochen, was sich zugetragen hat."}},
[93127] = {"Gipfelwachen", {"Aktiviert die Wächtersteine im Norden, Westen und Süden rund um die Blackthorne-Kultisten."}},
[93128] = {"Khan Jehn", {"Wahrt Euren Ruf bei den Gelkis und besiegt Khan Jehn im Dorf Magram. Erstattet danach Bericht bei Uthek der Weisen im Dorf Gelkis in Desolace."}},
[93129] = {"Gefahr des Hungertodes", {"Wahrt Euren Ruf bei den Magram und bringt 6 gestohlene Vorräte zurück zu Hagiak an der Front der Magram."}},
[93159] = {"Der seltsame Einsiedler", {"Sprecht mit dem seltsamen Einsiedler im Schattenwindwald und erfahrt mehr über ihn."}},
[93160] = {"Die Schätze des Waldes", {"Sammelt 8 Schattenwindeicheln."}},
[93161] = {"Der uralte Griff", {"Findet jemanden, der sich für den uralten Griff interessieren könnte, den Ihr in den Ruinen von Ban'aethal gefunden habt."}},
[93162] = {"Kopf des Vernichters", nil},
[93165] = {"Unerhörte Gnade", {"Sammelt 5 Ohren von Al'Aketh-Kultisten im Schattenwindwald, beim Schrein von Akir oder im Böenbeerentiefland."}},
[93172] = {"Die Hüllen befreien", {"Zerstört 10 Windhüllen im Schattenwindwald."}},
[93176] = {"Meine kleinen Freunde", {"Benutzt die Gegenstände aus dem Einsteigerpaket für Entomologen, um eine Laubengangtarantel, einen Heurüsselkäfer und einen Fleischpflücker zu finden und einzufangen."}},
[93188] = {"Zurück zu Orgrul", {"Wahrt Euren Ruf bei den Magram und erstattet Orgrul in der Nähe des nördlichen Eingangs zum Tal der Knochen Bericht."}},
[93196] = {"Khan Jehn", {"Wahrt Euren Ruf bei den Magram und vollführt ein nekromantisches Ritual, um Khan Jehn wiederzubeleben. Die Ritualstätte findet Ihr in einem Zelt beim zentralen See im Dorf Magram."}},
[93197] = {"Instandsetzung der Kommunikation", {"Bringt die Postpakete von Sebelia aus dem Gipfellager am Hyjal zu Gastwirt Vizzie in Everlook."}},
[93224] = {"Geschnitzte Zentaurentotem", {"Sammelt 5 geschnitzte Zentaurentotems, indem Ihr Zentauren aller Klans in Desolace tötet. Bringt sie dann zu Captain Pentigast auf der Nijelspitze."}},
[93225] = {"Geschnitzte Zentaurentotem", {"Sammelt 5 geschnitzte Zentaurentotems, indem Ihr Zentauren aller Klans in Desolace tötet. Bringt sie dann zu Gurda Wildmähne im Geistwandlerposten."}},
[93226] = {"Erkaufte Freundschaft: Magram", {"Bringt die Totemtasche zum Rüstmeister der Magram im Dorf der Magram in Desolace, um Euren Ruf bei diesem Klan deutlich zu erhöhen. Ihr müsst dem Magramklan gegenüber mindestens neutral eingestellt sein."}},
[93227] = {"Erkaufte Freundschaft: Gelkis", {"Bringt die Totemtasche zum Rüstmeister der Gelkis im Dorf der Gelkis in Desolace, um Euren Ruf bei diesem Klan deutlich zu erhöhen. Ihr müsst dem Gelkisklan gegenüber mindestens neutral eingestellt sein."}},
[93269] = {"Spitzen-Post", {"Bringt die Post von Everlook hoch zu Gastwirt Sebelia auf dem Gipfel von Hyjal."}},
[93317] = {"Krabbensaison", {"Sammelt 6 Stück Windweisenkriecherfleisch."}},
[93318] = {"GESUCHT: Vulgara der Unersättliche", {"Tötet Vulgara den Unersättlichen im Shen'darhochland and bringt ihren Kopf zu Danarii Bellowveil."}},
[93319] = {"Gestohlene Windsteine", {"Sammelt 10 gestohlene Windsteine von den Hochlandbanditen im Shen'darhochland."}},
[93320] = {"Turmverteidigung", {"Meldet Euch bei Yorana Windyreed im östlichen Wachturm im Böenbeerentiefland."}},
[93341] = {"Verlorene Gärten", {"Untersucht die Verlorenen Gärten in der Nähe von Shen'dralas und kehrt anschließend zurück zu Mithera im nahegelegenen Tempel."}},
[93362] = {"Keine Rosen ohne Dornen", {"Merzt Pflanzen im Verlorenen Garten aus und kehrt anschließend zurück zu Mithera in Shen'dralas."}},
[93383] = {"Inhalt unter Druck", {"Wartet, bis Ihr das persönliche Überlebenspaket sicher öffnen könnt"}},
[93394] = {"Ein Treffen mit dem Magister", {"Findet Magister Kirandis im Tempel von Shen'dralas."}},
[93404] = {"Fäulnis und Bedauern", {"Begebt Euch nach Maraudon und besorgt für Waldemar in den Verlorenen Gärten in Desolace eine Phiole mit Wasser aus den Fällen des Irdenen Gesangs."}},
[93406] = {"Frostfreie Lieferung", {"Findet 4 vermisste Post in den Hügeln nördlich von Everlook und bringt sie zurück zu Gastwirt Vizzie."}},
[93407] = {"Ein Dorn in der Tatze", {"Findet Dornensamen in den Wäldern am Gipfel von Hyjal und bringt sie zu Tiala Whitemane zurück."}},
[93422] = {"Blackthorne-Blackout", {"Tötet die Kurierin der Blackthorne und beschlagnahmt ihre Nachricht."}},
[93429] = {"Blut meines Blutes", {"Tötet 10 Verirrte im Fallow Heiligtum."}},
[93430] = {"Den Köder einholen", {"Findet den Angler der Verirrten, der Pelluks Köder gestohlen hat, und holt ihn zurück."}},
[93443] = {"Die verlorene Transportkiste", {"Bringt die verlorene Transportkiste zu Friz Frazzlespark im Hafen von Powderfuse in den Flusslanden zurück."}},
[93444] = {"Ein Köder für die Bestie", {"Tötet einen Nachtsäblerwächter am nördlichen Rand des Gipfels und lockt anschließend Ghansurok mit dem Schenkel des Nachtsäblerwächters hervor und tötet das Monster.","","Kehrt mit dem Herz der Schimäre zurück."}},
[93450] = {"Geisterhafte Probleme", {"Nehmt Vindaels unvollendetes Schwert und findet einen Weg, es in die Geisterwelt zu bringen. Bringt die geisterhafte Klinge anschließend zurück zu ihm nach Shen'dralas."}},
[93459] = {"Mehr Ohren der Al'Aketh", nil},
[93461] = {"Willkommen in Shen'dar", {"Sprecht mit Rathiril Sunlance und Coriella Calmbreeze in Shen'dar."}},
[93464] = {"Magier auf Besuch", {"Findet den Magier in Desolace, der von der Macht des Draenethyst weiß."}},
[93465] = {"Notizen über Draenethyst", {"Holt Gimashis Notizen über Draenethyst und bringt sie zu Azore Aldamort."}},
[93510] = {"Erinnerungen wecken", {"Findet den Anker am Immerruhsee, an den sich der Kriegsveteran aus seiner Kindheit erinnert."}},
[93521] = {"Götterdieb", {"Bringt Ve'hans Forschungsnotizen zu Tiala Whitemane."}},
[93546] = {"Spektraleisenerz", {"Sucht in der Umgebung von Shen'dralas nach Spektraleisenvorkommen und sammelt 10 Spektraleisenerze. Kehrt zu Vindael in Shen'dralas zurück, sobald Ihr genug gefunden habt."}},
[93547] = {"Eine dornige Lösung", {"Pflanzt Dornensamen in der Nähe des Gasthauses, des Lagerturms und der Baumgruppe im Lager der loyalistischen Druiden."}},
[93551] = {"Lob", {"Verwendet die geschmückte Waffenscheide, um den Veteranen des Dritten Krieges am Hyjal, neben der zerbrochenen Kanone in Klageruh, zu treffen."}},
[93552] = {"Windsteine anzapfen", {"Sammelt 15 Windsteinhaufen von rohen Windsteinen im Thendalhain."}},
[93567] = {"Das Ende aller Wege", {"Erlaubt dem Veteranen des Dritten Krieges neben der zerbrochenen Kanone in Klageruh, seine Geschichte zu erzählen."}},
[93568] = {"Teilweise verdautes Halsband", {"Bringt das teilweise verdaute Halsband zu jemandem, der mehr darüber weiß. In Shen'dralas in Desolace oder in unmittelbarer Umgebung davon sollte sich jemand finden lassen."}},
[93574] = {"Leichenfresserpanzer", {"Findet jemanden, der Interesse an dem Leichenfresserpanzer haben könnte."}},
[93584] = {"Das Ende eines Kults", {"Tötet 10 Adepten der Blackthorne und 10 wildnisgezeichnete Kultisten."}},
[93585] = {"Mein Licht", {"Begleitet Vater Tuttle zum Sicheren Hafen."}},
[93594] = {"Wort aus dem Wald", {"Findet Waldemar in den Verlorenen Gärten bei Shen'dralas in Desolace."}},
[93601] = {"Die Frage nach der Schuld", {"Sucht beim Rückzugsort der Borstennacken einen Stacheleber von Bedeutung auf."}},
[93604] = {"Agamaggans Blut", {"Begebt Euch zu den Hügeln von Razorfen und besorgt virulentes Blut von Agamaggan. Kehrt dann zu Kog'thug dem Tapferen im Rückzugsort der Borstennacken in Desolace. Kog'thug hielt es für nötig, Euch daran zu erinnern, dass das Blut von Agamaggan in den Kral von Razorfen nicht ausreicht."}},
[93615] = {"Streunende Kätzchen", {"Sucht in der Wildnis auf dem Hyjal nach Shalla'kals Kätzchen."}},
[93617] = {"Jäger und Gejagte", {"Bringt die Hirsche davon ab, sich wie Raubtiere aufzuführen."}},
[93644] = {"Zerlumptes Tagebuch", {"Der Text deutet darauf hin, dass sich der Verfasser dieses Tagebuchs irgendwo in Shen'dralas befinden könnte."}},
[93663] = {"Auf dem Sendungsweg verloren", {"Findet den vermissten Kurier und stellt sicher, dass Dars Lieferung im Sicheren Hafen ankommt."}},
[93678] = {"Gekürzte Notizen über Draenethyst", {"Bringt Azores abgeschriebene Notizen zu Magtoor im Sicheren Hafen in den Sümpfen des Elends."}},
[93680] = {"Schlüssel zur Stadt", {"Holt den Kanalisationsschlüssel von Dalaran für Magus Wordeen Voidglare in Tarrens Mühle."}},
[93684] = {"Der Gefundene", {"Findet den Draenei, der nach Draenethyst sucht, in den Verwüsteten Landen."}},
[93685] = {"Ein Dienst für Kum'isha", {"Findet eine fehlerlose Draenethystsphäre in den Verwüsteten Landen und bringt sie zu Kum'isha dem Sammler.","","Doch seid gewarnt. Der Edelstein ist einer der rarsten Kristalle von ganz Azeroth. Jedes Wesen in diesem Land könnte eine fehlerlose Draenethystsphäre bei sich haben."}},
[93735] = {"Das kaputte Konstrukt", {"Findet Riaani Nightwind im westlichen Teil von Valanaar."}},
[93736] = {"Unerwünschte Geister", {"Sammelt 10 Windhüllenessenzen von Windhüllen im Schattenwindwald."}},
[93737] = {"Das kaputte Konstrukt", {"Sprecht mit Rianni Nightwind und hört, was er zu sagen hat."}},
[93738] = {"Das kaputte Konstrukt", {"Erstattet Ayessa Dawnsinger in Valanaar Bericht."}},
[93739] = {"Erkundung der Horde", {"Sprecht mit Nazgrel in der Festung Grommash, um weitere Hinweise zu erhalten. Befolgt die erhaltenen Hinweise, um Vol'jin, Cairne Bloodhoof und Fürstin Sylvanas Windrunner aufzusuchen und mit ihnen zu sprechen."}},
[93740] = {"Blut für Blut", {"Sammelt 10 Windsteinamulette der Al'Aketh von toten Kultisten im Böenbeerentiefland."}},
[93746] = {"Eine entschiedene Reaktion", {"Konfrontiert Belathaan Brightwish auf der Straße zum Schrein von Akir."}},
[93747] = {"Von Gewalt zu Vegetation", {"Pflanzt die verzauberten Samen in der Nähe der zerstörten Balliste, des zerstörten Katapults und der zerstörten Flugmaschine."}},
[93759] = {"Die Fülle der Natur", {"Sammelt 2 Stücke Wildfleisch von unbefleckten Hyjalhirschen und 6 scharlachrote Wurmknollen für den Eintopf des Einsiedlers."}},
[93773] = {"Der Pakt", {"Erstattet Ketharas auf dem Hyjal Bericht."}},
[93786] = {"Eine blutige Botschaft", {"Tötet 12 Landarbeiter aus Wiesenbach und kehrt dann zu Krom'rosh zurück, um ihm von Eurem Erfolg zu berichten."}},
[93787] = {"Das Füllhorn plündern", {"Stehlt 6 Futterbeutel von der Allianzfarm in Wiesenbach und kehrt zu Krom'rosh zurück."}},
[93788] = {"Geliehene Klingen", {"Erbeutet 10 Äxte des Holzarbeiters von den Holzfällern bei Turners Holzfällerlager für Kreza Darkthorn in Rog'mar."}},
[93791] = {"Sprecht mit Belann", {"Sprecht mit Belann Windwood in Valanaar."}},
[93797] = {"Zweige im Wind", {"Bringt einen winddurchfluteten Zweig zu Belann Windwood in Valanaar."}},
[93825] = {"Baumrindensegen", {"Sammelt 12 Klumpen Mondschleiermoos und kehrt zu Suma Mossmane zurück."}},
[93826] = {"Tod den Totenwaldfellen", {"Tötet 8 Totemiker der Totenwaldfelle und 8 Teufelspfleger der Totenwaldfelle und kehrt zum Ältesten Pinespeaker zurück."}},
[93827] = {"Tosender Schutz des Windes", {"Sammelt 16 verzauberte Harpyienamulette und kehrt zu Thobon Sapclaw zurück."}},
[93831] = {"Süßtatzenmarmelade", {"Sammelt 30 Bärenbeeren von Hyjal und kehrt zu Osi Mistpaw zurück."}},
[93835] = {"Konfrontiert Lorthuna", {"Nehmt das Portal zu den Türmen der Rohashi oben und schließt Euch Elaadrin Evengale und Ayessa Dawnsinger bei ihrer Konfrontation mit der Hohepriesterin Lorthuna an."}},
[93836] = {"Das Schicksal Zephras'", {"Sprecht mit Talaanis Shadowsong in Valanaar."}},
[93848] = {"Gute Arbeit", {"Kehrt zu Ketharas zurück und berichtet ihm von den Ereignissen am Gipfel der Ewigkeit."}},
[93925] = {"Perlen für Brerufa", nil},
[93926] = {"Die Westwacht", {"Findet Friedensbewahrer Vaaniel im westlichen Wachturm."}},
[93927] = {"Eine letzte Bitte", {"Hebt die Notiz auf, die Ihr bei dem toten Friedensbewahrer gefunden habt, um über Eure nächsten Schritte zu entscheiden."}},
[93948] = {"Überbringt das Siegel", {"Überbringt das Siegel der Familie Shadowsong an Talaanis Shadowsong in Valanaar."}},
[93949] = {"Geplagt", {"Tötet Himmelshüpfer in Valanaar, bis Ihr 8 verzauberte Himmelshüpfer eliminiert habt."}},
[93951] = {"Ein wenig Schönheit", {"Sammelt 8 Hippogryphendaunen im Shen'darhochland."}},
[93952] = {"Gestärktes Gleichgewicht", {"Bezwingt 9 Höhlenwächter der Totenwaldfelle und kehrt zu Brerufa zurück."}},
[93958] = {"Das Innere Sanktum", {"Sprecht mit Valanaar Stormfist im inneren Sanktum beim Schrein von Akir."}},
[93963] = {"Erkundung der Allianz", {"Sprecht mit Randal Emerson in der Burg Stomwind, um weitere Hinweise zu erhalten. Nutzt die erhaltenen Hinweise, um König Magni Bronzebeard, Hochtüftler Mekkatorque und Tyrande Whisperwind aufzusuchen und mit ihnen zu sprechen."}},
[93976] = {"Die Goblinhändlerin", {"Bringt die Klinge zu Kreza Darkthorns Bekannten bei den Docks östlich von Rog'mar."}},
[94003] = {"Das Bollwerk der Himmelsbrecher", {"Holt das Bollwerk der Himmelsbrecher von Zaal Stormshield am Schrein von Akir zurück."}},
[94004] = {"Handwerksverfügung: Elixier der Ogerstärke", {"Besorgt die vom Kunden angeforderten Gegenstände und liefert sie an die auf Eurer Karte markierte Position. Dieses Schriftstück muss sich in Eurem Besitz befinden, um die Transaktion abzuschließen."}},
[94006] = {"Der große Urserageist", {"Sprecht mit Urs'endris in der Nähe der Wasserfälle im Nordosten von Valanaar."}},
[94007] = {"Die Bestie zähmen", {"Meldet Euch bei Quel'ana Quickgale in Valanaar."}},
[94013] = {"Die Bestie zähmen", {"Benutzt die Zähmerrute, um einen Vuldrenalpha im Böenbeerentiefland zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmerrute dann zu Quel'ana Quickgale in Valanaar zurück."}},
[94050] = {"Die Bestie abrichten", {"Sprecht mit Quel'dora Quickgale in Valanaar."}},
