[96964] = {"Eine gerissene Kreatur", {"Sprecht mit dem wilden Gott Renalard."}},
[96971] = {"Die Fabel von dem Fuchs und dem Dämon", {"Sammelt 8 zurückgelassene Ausrüstungsgegenstände."}},
[96978] = {"Aggressives Wildbret", {"Sprecht mit dem wilden Gott Kala'th."}},
