[96984] = {"Das Herz der Störung", {"Holt den Arkanpartikel für Magus Wordeen Voidglare in Tarrens Mühle aus Dalaran."}},
[96986] = {"Der Grabritter", {"Besiegt Atrexis den Grabritter in Dalaran für Melisara in Tarrens Mühle."}},
[96987] = {"Opportunistische Bildung", {"Holt das Buch \"Die Gründung von Dalaran\" aus Dalaran für Rexxie Copperclutch in der Nähe des Kanalisationseingangs."}},
[96988] = {"Quelle der Macht", {"Sammelt 6 gesprungene Wächterkerne in Dalaran für Doktor Martin Felben in Undercity."}},
[96989] = {"Euer erster Reitraptor", {"Inspiziert die reitbaren Raptoren, um Euer erstes Reittier zu wählen."}},
[96991] = {"Fährtenhilfe", {"Liefert Galvinquams Habseligkeiten bei Marn Euhron am Gipfel ab."}},
[96992] = {"Nachschub", {"Sucht in den ausgebrannten Gebäuden der Wiege der Ruhe nach 6 Metallklammern und 30 Nägeln und bringt sie Johun \"Haudrauf\" Dillis in Hyjal."}},
[96994] = {"Euer erster Reitwolf", {"Inspiziert die reitbaren Wölfe, um Euer erstes Reittier zu wählen."}},
[96996] = {"Euer erster Windschreiter zum Reiten", {"Inspiziert die reitbaren Schreiter, um Euer erstes Reittier zu wählen."}},
[96997] = {"Ein Ross im Tode wie im Leben", {"Inspiziert die untoten Reitpferde, um Euer erstes Reittier zu wählen."}},
[96999] = {"Rollenrückgabe", {"Gebt die Kriegsbemalungsrolle jemandem in Sen'jin."}},
[97000] = {"Bleibendes Andenken", {"Durchsucht die zerstörten Lager der Allianz am Hyjal nach Hinweisen auf Abigail Sawyers Vater Lawrence."}},
[97003] = {"Chol'aruk der Verschlinger", {"Bringt den Kopf von Chol'aruk zu Gur'ak im Brachland."}},
[97005] = {"Chol'aruk der Verschlinger", {"Bringt Chol'aruks Kopf zu Bainham im Brachland."}},
[97009] = {"Maerions Elend", {"Bringt 12 Teufelshundstacheln zu Maerion Thaelemaches in Dae'gun."}},
[97010] = {"Blinde Rache", {"Steigt auf die Spitze des Magierturms der Horde und werft einen explosiven Runensplitter ab, um Maerion Thalemaches das Signal zum Angriff auf die Dämonen zu geben."}},
