[97179] = {"Materialsammlung", {"Bringt 40 Lagen Runenstoff, 6 Arkanitbarren, 10 Arthas' Tränen, 5 Phiolen Weihwasser aus Stratholme und 150 Gold zu Ott im Vorgebirge von Hillsbrad."}},
