[97386] = {"Die Offensive von Grom'gol", {"Kommandant Aggro'gosh vom Basislager von Grom'gol will, dass Ihr Oger beim Ogerhügel der Mosh'Ogg tötet."}},
[97405] = {"Lärmbeschwerden", {"Knaz Blunderflame möchte, dass Ihr 3 Zauberkundige der Mosh'Ogg, 3 Kriegstreiber der Mosh'Ogg, 3 Zermalmer der Mosh'Ogg Maulers und 3 Schamanen der Mosh'Ogg auf dem Ogerberg der Mosh'Ogg tötet."}},
[97411] = {"Ein aufrichtiges Angebot", nil},
[97420] = {"Verringerung, Verwertung, Versöhnung", {"Besorgt 4 Fässer mit Rohöl aus den Operationen der Venture Co. am Nazferitisee und kehrt dann zu Knaz Blunderflame im Schlingendorntal zurück."}},
[97453] = {"Schönheitsschnitt", {"Tötet 6 fleischfressendes Unkraut südlich von Grom'gol und informiert dann Gemmils Mutter."}},
[97485] = {"Traditionen von Thunder Bluff", {"Kauft ein Kräuterbündel von Nida der Kräuterkundigen, ein Bündel Zedernzweige von Nata, der Verkäuferin für Verzauberkunstbedarf, und Sehnenfaden von Mahu, dem Verkäufer für Lederverarbeitungsbedarf, sowie Feuerstein und Zunder von Naal, dem Verkäufer für Kochbedarf.","","Fügt die Gegenstände zusammen und streut das Räucherwerk von der Anhöhe der Jäger."}},
[97490] = {"Hitzeschutz von Hagelschuft", {"Sucht in den südlichen Hügeln von Winterspring nach dem Riesen namens Hagelschuft und besorgt das Frostmoos, das auf ihm wächst."}},
[97530] = {"Was die Dünenbrecher stahlen", {"Sicherheitschef Bilgewhizzle aus Steamwheedle in Tanaris möchte, dass Ihr einen besonders glänzenden Armreif zurückbringt, der irgendwo beim Lager der Oger der Dünenbrecher verloren ging."}},
[97534] = {"Ein schmutziges Geschäft", {"Quinn möchte, dass Ihr 7 Haufen Wüstenschutt sammelt und zu ihr nach Gadgetzan bringt."}},
[97536] = {"Gnomischer Müll", {"Jhordy Lapforge möchte, dass Ihr zu ihm zurückkehrt, nachdem Ihr die Kiste mit radioaktiven Abfällen in der Wüste von Tanaris entsorgt habt, in sicherer Entfernung von Gadgetzan und anderem Müll."}},
[97538] = {"Pigmente für Farben", {"Tah Winterhoof in Thunder Bluff möchte 30 Mirkkrautsamenkapseln vom Mirkfallonsee."}},
[97539] = {"Am seidenen Faden", {"Bringt 12 Stücke chirurgischer Spinnenseide zu Doktor Gregory Victor in Hammerfall, Arathihochland."}},
[97540] = {"Oase", {"Bringt den frisch erquickten Tooga zurück zu seiner Frau Torta."}},
[97558] = {"Häute, Bälge, Membranen", {"Bringt Shelene Rhobart 8 Nachtsaugerflügelmembranen, 6 Schattenhundbälge und 3 Häute eines Murlocs der Finsterflossen."}},
[97583] = {"GLIBBER.", {"Kauft nahrhafte Schleimpampe und kehrt zu Eurem freundlichen erregbaren Schleim zurück. Versucht, mit ihm zu tanzen, wenn er müde wirkt, um wieder seine Aufmerksamkeit zu erregen."}},
[97617] = {"Sicherheitskontrolle", {"Bergt 8 nicht studierte Artefakte, einen Bergbauhelm der Forscherliga sowie eine makellose Kreuzhacke und bringt alles zu Dorgaron an der Grenze zu Loch Modan und dem Ödland."}},
[97663] = {"Vorräte und Forscherdrang", {"Tötet Oger im Staubbecken für Mus'hales gestohlene Vorräte und fertigt damit Abdrücke der hiesigen Steinschnitzereien an. Kehrt dann zu Mus'hale in Kargath zurück."}},
[97884] = {"Waffenkammer von Sonnengrund", {"Reist nach Sonnengrund in den Flusslanden und besorgt den Folianten der Schmiedetechniken der Familie Tremayne."}},
[97891] = {"Zügige Tranklieferung", {"Bringt den instabilen Trank zu Doktor Martin Felben im Apothekarium, bevor die Zeit abläuft."}},
[97894] = {"Geschäfte in Auberdine", {"Seht nach Gorbold Steelhand in Auberdine in Dunkelküste.","","Borgus hat ein Boot am südlichsten Dock im Hafen von Stormwind erwähnt, das Euch dorthin bringen kann."}},
[97899] = {"Grundlagen des Zeltens: Alchimie", {"Geht nach Orgrimmar und sprecht mit Whuut, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt."}},
